INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(60, 'Pengacara Majlis', 'Pengacara yang mengendalikan majlis rasmi.', 'Mengumumkan majlis dan bertanya tentang lambang negeri.', 'gadis_melayu.png'),
(61, 'Pemuzik Warisan', 'Pemuzik tua yang membawa gambus, sape dan gendang dari kampung ke kampung.', 'Memelihara rentak muzik pelbagai kaum supaya warisan bunyi tidak hilang.', 'pemuzik_ulung.png'),
(62, 'Nenek Segala Kaum', 'Warga emas yang menyimpan cerita petempatan dan legenda setiap kaum (watak rekaan).', 'Menurunkan cerita kaum kepada cucu-cucu supaya mereka mengenali jiran sendiri.', 'nenek_dahulu.png'),
(63, 'Tok Permainan', 'Penjaga gelanggang permainan tradisional yang menyatukan kanak-kanak segala kaum.', 'Memastikan permainan warisan terus dimainkan oleh semua kaum bersama-sama.', 'tok_permainan.png'),
(64, 'Aishah', 'Gadis Melayu yang peramah dan petah bertanya (watak rekaan).', 'Mewakili anak muda Melayu yang ingin mengenali kaum lain.', 'gadis_melayu.png'),
(65, 'Kavitha', 'Gadis India yang ceria dan pandai menari (watak rekaan).', 'Mewakili anak muda India yang bangga dengan warisan kaumnya.', 'gadis_india.png'),
(66, 'Linda', 'Gadis Kadazandusun dari Sabah yang gemar bercerita (watak rekaan).', 'Mewakili anak muda Sabah yang menjaga cerita dan tarian kaumnya.', 'gadis_sabah.png'),
(67, 'Jenny', 'Gadis dari Sarawak yang bersemangat dan suka berjenaka (watak rekaan).', 'Mewakili anak muda Sarawak yang bangga dengan kaum dan negerinya.', 'gadis_sarawak.png'),
(68, 'Apai Iban', 'Orang tua Iban yang gagah dan pandai bercerita tentang lembah sungai (watak rekaan).', 'Mewakili masyarakat Iban di lembah sungai Sarawak.', 'sarawakian.png'),
(69, 'Ah Meng', 'Pemuda Cina yang bertenaga dan suka bergurau (watak rekaan).', 'Mewakili anak muda Cina yang suka mencuba semua permainan dan muzik.', 'lengchai_cina.png'),
(70, 'Tok Batin', 'Orang tua Orang Asli yang tenang dan mahir hasil hutan (watak rekaan).', 'Mewakili masyarakat Orang Asli di pedalaman Semenanjung.', 'orang_tradisi_lama.png'),
(71, 'Pak Bajau', 'Lelaki Bajau dari Sabah yang peramah (watak rekaan).', 'Mewakili kaum lain di Sabah dalam kepelbagaian kaum.', 'orang_bajau.png'),
(72, 'Si Luncai', 'Watak cerita rakyat yang bijak memperdaya dengan labu-labunya.', 'Melambangkan akal yang bijak dalam cerita rakyat Melayu.', 'si_luncai.png'),
(73, 'Puteri Santubong', 'Puteri kayangan dalam legenda Santubong yang pandai menenun.', 'Mewakili legenda asal usul Gunung Santubong di Sarawak.', 'puteri_santubong.png'),
(74, 'Murid Sekolah', 'Murid yang gemar bertanya dan bertenaga (watak rekaan).', 'Mewakili generasi muda yang mewarisi budaya pelbagai kaum.', 'budak_gajet.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(401, 'Rentak Seribu Kaum', 4, 'Masuki peranan seorang pemuzik tua yang mengembara dari kampung ke kampung membawa gambus, sape dan gendang. Dalam setiap rentak kau mengenali kaum, alat muzik dan tarian tradisional Malaysia.'),
(402, 'Peti Cerita Nenek', 4, 'Masuki peranan Nenek Segala Kaum yang membuka peti cerita lamanya. Dari laci ke laci, kau mengajar cucu-cucu tentang petempatan dan ekonomi dahulu serta kini, dan tiga cerita rakyat.'),
(403, 'Gelanggang Seribu Kaum', 4, 'Masuki peranan Tok Permainan yang menjaga gelanggang tempat semua kaum bermain bersama. Setiap pusingan mengajarmu permainan tradisional, legenda Nunuk Ragang dan nilai toleransi.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e4_n1_s1', 'Malam perayaan di sebuah padang kampung. Lampu pentas dipasang dan penonton pelbagai kaum datang. Di tangan pemuzik ada senarai bahasa setiap kaum yang bercampur-baur.', 1, 401, 'alat_muzik_dan_tarian_tradisional.png'),
('e4_n1_s2', 'Pinggir hutan di Perak. Tok Batin duduk di hadapan rumah buluh sambil menganyam bakul. Ubat herba dan kraf tangan tersusun di atas tikar, namun sebuah kad nota tertinggal di tepi.', 2, 401, 'petempatan_orang_asli_dahulu.png'),
('e4_n1_s3', 'Pasar malam di bandar Melaka. Kedai kuih, pasar tamu dan restoran berjejer. Empat kad kaum peranakan dan kaum kecil berselerak di atas meja pemuzik.', 3, 401, 'petempatan_semua_kini.png'),
('e4_n1_s4', 'Tebing sungai di Sarawak. Rumah panjang berjejer di tepi air, tikar pua kumbu dijemur. Apai Iban dan Linda dari Sabah berbalah tentang kaum mana lebih besar.', 4, 401, 'petempatan_lembah_sungai_sarawak.png'),
('e4_n1_s5', 'Pentas besar dengan lima sudut persembahan. Setiap sudut mempunyai alat muzik dan penari, namun papan petunjuk jatuh sehingga penonton keliru.', 5, 401, 'alat_muzik_dan_tarian_tradisional.png'),
('e4_n1_s6', 'Bengkel alat muzik di belakang pentas. Buluh, kayu dan kulit terbentang di atas meja. Seorang murid berkeras hendak menggantikan semuanya dengan alat elektronik.', 6, 401, 'alat_muzik_dan_tarian_tradisional.png'),
('e4_n1_s7', 'Tirai pentas hampir dibuka. Lapan penari bersiap, namun senarai tarian bercampur. Pengurus pentas bimbang acara bermula tanpa susunan yang tepat.', 7, 401, 'alat_muzik_dan_tarian_tradisional.png'),
('e4_n1_s8', 'Malam di kampung Orang Asli. Api unggun menyala dan penari bersedia. Dua kad tarian, sewang dan bhangra, tertukar di atas tikar.', 8, 401, 'petempatan_orang_asli_dahulu.png'),
('e4_n2_s1', 'Laci pertama dalam peti nenek terbuka. Gambar kampung tepi sungai, perahu nelayan dan sawah padi memenuhi pandangan. Cucu-cucu duduk bersila.', 1, 402, 'petempatan_melayu_dahulu.png'),
('e4_n2_s2', 'Laci kedua. Gambar lombong bijih, jalan pekan dan rumah kedai bertingkat. Kavitha dan Ah Meng berbalah sama ada kaum mereka dahulu tinggal di tempat yang sama.', 2, 402, 'petempatan_cina_dahulu.png'),
('e4_n2_s3', 'Laci ketiga. Gambar rumah buluh di pedalaman, anyaman rotan dan kulit kayu kering. Cucu bertanya sama ada Orang Asli hanya tinggal di satu negeri.', 3, 402, 'petempatan_orang_asli_dahulu.png'),
('e4_n2_s4', 'Laci keempat. Gambar Sarawak, iaitu pedalaman berbukit, lembah sungai dan pantai. Jenny dan Apai Iban berbalah tentang tempat tinggal kaum mereka.', 4, 402, 'petempatan_pedalaman_sarawak_dahulu.png'),
('e4_n2_s5', 'Laci kelima. Gambar Sabah, iaitu pedalaman bersawah, pantai nelayan dan perahu berlabuh. Linda dan Pak Bajau saling bertanya tentang kampung datuk mereka.', 5, 402, 'petempatan_pedalaman_sabah.png'),
('e4_n2_s6', 'Taman perumahan masa kini. Jiran Melayu, Cina, India dan kaum lain berkumpul untuk gotong-royong. Cucu bertanya mengapakah kini tidak seperti dalam laci lama.', 6, 402, 'petempatan_semua_kini.png'),
('e4_n2_s7', 'Laci ketujuh. Sebuah perahu di tengah laut, guni di atas papan dan labu-labu air berguling di dalamnya. Si Luncai tersenyum licik dari dalam guni.', 7, 402, 'si_luncai.png'),
('e4_n2_s8', 'Laci terakhir. Gunung Santubong terbentang di pandangan, dan dua puteri kayangan bertelingkah di bawah kilat. Dua kampung berjiran, Pasir Kuning dan Pasir Putih, mengintai dari jauh.', 8, 402, 'puteri_santubong.png'),
('e4_n3_s1', 'Pagi Sabtu di gelanggang. Anjung rumah, laman luas dan padang lapang berjejer. Kanak-kanak tidak bersetuju di mana permainan harus dimainkan.', 1, 403, 'permainan_tradisional.png'),
('e4_n3_s2', 'Meja kayu di anjung. Papan congkak, lima biji batu, buah hitam dan putih dan bola lawi tersusun, namun nama permainan tercabut dan bercampur-baur.', 2, 403, 'permainan_tradisional.png'),
('e4_n3_s3', 'Padang lapang selepas musim menuai. Wau berterbangan, gasing berputar dan tiang tinggi dipasang. Empat kad permainan lapang diletakkan di atas tikar.', 3, 403, 'permainan_tradisional.png'),
('e4_n3_s4', 'Sudut gelanggang berasingan. Papan catur India dan dadu, yoyo diabolo dan papan go diletakkan di meja. Kanak-kanak bertanya sama ada permainan ini datang dari luar.', 4, 403, 'permainan_tradisional.png'),
('e4_n3_s5', 'Papan kenyataan di pintu gelanggang. Senarai permainan yang diangkat sebagai warisan kebangsaan negara tertulis separa terpadam.', 5, 403, 'permainan_tradisional.png'),
('e4_n3_s6', 'Tepi Sungai Liwagu di Sabah. Sebatang pohon nunuk besar menaungi penduduk yang berehat. Seekor ayam gergasi berwarna merah dan bertaji emas turun mengibas sayap.', 6, 403, 'nunuk_ragang.png'),
('e4_n3_s7', 'Taman permainan di kawasan perumahan. Dua kumpulan kanak-kanak berbalah kerana kumpulan lain bercakap bahasa yang tidak difahami. Tok Permainan datang melerai.', 7, 403, 'petempatan_semua_kini.png'),
('e4_n3_s8', 'Pameran budaya di dewan sekolah. Gambar alat muzik, tarian dan permainan terpampang. Ada pelancong asing mengambil gambar, dan murid mempersoalkan gunanya semua ini.', 8, 403, 'petempatan_semua_kini.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(401, 'e4_n1_s1', 'Senarai Bahasa Kaum', 'Padankan setiap kaum dengan bahasa pertuturannya.', '4', 'Mengenal pasti kepelbagaian kaum di Malaysia dan bahasa pertuturan masing-masing.', '{"pairs": [{"text": "Melayu", "pair": 1}, {"text": "Bahasa Melayu", "pair": 1}, {"text": "Cina", "pair": 2}, {"text": "Mandarin, Hokkien, Hakka dan Kantonis", "pair": 2}, {"text": "India", "pair": 3}, {"text": "Tamil, Telugu dan Malayalam", "pair": 3}, {"text": "Sikh", "pair": 4}, {"text": "Bahasa Punjabi", "pair": 4}, {"text": "Serani", "pair": 5}, {"text": "Bahasa Kristang dan bahasa Inggeris", "pair": 5}, {"text": "Baba dan Nyonya", "pair": 6}, {"text": "Dialek Melayu Baba", "pair": 6}], "aftermath": "Senarai bertukar dan pengacara menyebut bahasa yang salah. Penonton tersinggung dan bertepuk sumbang.", "turns": [{"after": 6, "options": [{"text": "Bagi aku, setiap kaum ada bahasa sendiri dan keunikan itu perlu dihargai.", "isCorrect": true, "reaction": "Betul, pakcik. Pengacara mula menyebut tiga bahasa dan penonton tersenyum."}, {"text": "Bagi aku, semua kaum patut bercakap satu bahasa di pentas, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Penonton berbisik tidak puas hati kerana bahasa ibunda mereka diketepikan."}, {"text": "Sebenarnya, bahasa lain tidak penting untuk diketahui, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Kanak-kanak lain terdiam dan berasa bahasa mereka disisih."}], "clue": "Hargai keunikan bahasa setiap kaum."}]}'),
(402, 'e4_n1_s2', 'Nota Tok Batin', 'Baca nota dan tentukan tiga kumpulan terbesar Orang Asli di Semenanjung.', '5', 'Mengenal pasti tiga kumpulan terbesar Orang Asli: Negrito (Semang), Senoi dan Melayu Proto.', '{"clueText": "Nota Tok Batin: Di Semenanjung Malaysia, Orang Asli terbahagi kepada tiga kumpulan terbesar. Mereka istimewa kerana mengekalkan kemahiran kraf tangan, ubat-ubatan herba dan bahasa mengikut suku.", "options": [{"text": "Negrito (Semang), Senoi dan Melayu Proto.", "isCorrect": true}, {"text": "Iban, Bidayuh dan Melanau.", "isCorrect": false, "consequence": "Itu kaum di Sarawak. Tok Batin menggeleng dan budak bandar malu."}, {"text": "Baba, Chetti dan Serani.", "isCorrect": false, "consequence": "Itu kaum peranakan di bandar. Tok Batin menyuruh kau membaca semula."}, {"text": "Murut, Rungus dan Bajau.", "isCorrect": false, "consequence": "Itu kaum di Sabah. Kampung ketawa kecil dan kau tersipu."}], "aftermath": "Nota disalah baca dan tiga kumpulan itu keliru. Tok Batin berasa warisan mereka tidak dihargai.", "turns": [{"after": 5, "options": [{"text": "Orang Asli bukan kaum yang sama dengan kaum di Sarawak dan Sabah. Mereka ada tiga kumpulan sendiri.", "isCorrect": true, "reaction": "Betul, nak. Sekarang kau mengenali kami dengan tepat."}, {"text": "Aku fikir semua kaum pribumi sama sahaja, kerana tiada siapa yang akan peduli dan itu lebih senang.", "isCorrect": false, "reaction": "Tok Batin menarik nafas panjang. Kenyataan itu mengabaikan keunikan kami."}, {"text": "Orang Asli hanya wujud di Sabah, jadi cukup dibiarkan begitu sahaja dan ramai orang buat begitu.", "isCorrect": false, "reaction": "Kampung terdiam. Orang Asli sebenarnya tinggal di Semenanjung."}], "clue": "Tiga kumpulan, bukan sama dengan kaum lain."}]}'),
(403, 'e4_n1_s3', 'Kad Kaum Peranakan dan Kaum Kecil', 'Padankan kaum dengan cirinya.', '4', 'Mengenal pasti Baba dan Nyonya, Chetti, Serani, Siam dan Sikh beserta ciri masing-masing.', '{"pairs": [{"text": "Baba dan Nyonya", "pair": 1}, {"text": "Perkahwinan pedagang China dengan penduduk tempatan di Melaka", "pair": 1}, {"text": "Chetti", "pair": 2}, {"text": "Perkahwinan pedagang India dengan penduduk tempatan, bahasa Melayu kreol", "pair": 2}, {"text": "Serani", "pair": 3}, {"text": "Orang Eurasia, tarian branyo dan frapeirra", "pair": 3}, {"text": "Siam", "pair": 4}, {"text": "Menyambut Songkran dan beribadat di wat", "pair": 4}, {"text": "Sikh", "pair": 5}, {"text": "Sarban, bahasa Punjabi dan tarian bhangra", "pair": 5}], "aftermath": "Kad berselerak dan ciri kaum tersalah letak. Pelanggan pasar tersinggung apabila kaum mereka disalah sebut.", "turns": [{"after": 6, "options": [{"text": "Mereka menjadi kaum tersendiri dengan bahasa, adat dan makanan yang unik.", "isCorrect": true, "reaction": "Itu jawapan yang menghormati mereka, pakcik."}, {"text": "Mereka hanya ikut kaum lain, jadi tiada keunikan dan lupakan sahaja.", "isCorrect": false, "reaction": "Penjual kuih menarik muka masam. Budaya mereka bukan tiruan."}, {"text": "Mereka tidak termasuk dalam kepelbagaian kaum, kerana kita tidak rugi apa-apa.", "isCorrect": false, "reaction": "Sikh dan Chetti berasa disisih daripada senarai kaum negara."}], "clue": "Setiap kaum ada keunikan tersendiri."}]}'),
(404, 'e4_n1_s4', 'Catatan Dua Kaum Terbesar', 'Baca catatan dan tentukan kaum terbesar di Sarawak dan Sabah.', '5', 'Mengenal pasti kaum terbesar di Sarawak (Iban) dan Sabah (Kadazandusun).', '{"clueText": "Catatan: Merupakan kaum terbesar di Sarawak, kaum ini bertutur dalam bahasa Iban. Di Sabah pula, kaum terbesar bertutur mengikut dialek sukuan masing-masing dan memakai pakaian tradisional semasa Pesta Kaamatan.", "options": [{"text": "Iban di Sarawak dan Kadazandusun di Sabah.", "isCorrect": true}, {"text": "Bidayuh di Sarawak dan Bajau di Sabah.", "isCorrect": false, "consequence": "Bidayuh dan Bajau memang ada, tetapi bukan yang terbesar. Apai Iban berkerut dahi."}, {"text": "Melanau di Sarawak dan Murut di Sabah.", "isCorrect": false, "consequence": "Dua kaum ini bukan yang terbesar. Linda menggeleng kepala."}, {"text": "Kayan di Sarawak dan Rungus di Sabah.", "isCorrect": false, "consequence": "Catatan tidak menyebut kaum itu. Kau dipandang hairan."}], "aftermath": "Catatan tersilap baca dan pengunjung diberi maklumat yang salah tentang kaum terbesar di Sarawak dan Sabah.", "turns": [{"after": 5, "options": [{"text": "Kedua-duanya terbesar di negeri masing-masing, dan keunikan kedua-duanya wajar dihargai.", "isCorrect": true, "reaction": "Itu cara yang adil, dan kami berdua tersenyum."}, {"text": "Hanya Iban yang penting kerana Sarawak lebih besar dan tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Linda tersinggung dan perbalahan negeri bermula."}, {"text": "Hanya Kadazandusun yang penting kerana Sabah lebih makmur dan kita tidak rugi apa-apa.", "isCorrect": false, "reaction": "Apai Iban berpaling muka dan majlis menjadi dingin."}], "clue": "Kedua-duanya terbesar di negeri masing-masing."}]}'),
(405, 'e4_n1_s5', 'Cari Lima Sudut Pentas', 'Cari lima sudut pentas yang mewakili Melayu, Cina, India, Sarawak dan Sabah.', '2', 'Mengenal pasti alat muzik dan tarian mengikut kaum: Melayu, Cina, India, Sarawak dan Sabah.', '{"bgImage": "../assets/gameAsset/background/alat_muzik_dan_tarian_tradisional.png", "hotspots": [{"name": "Pentas Melayu: gambus dan angklung; tarian makyung dan zapin", "top": "25%", "left": "32%"}, {"name": "Tarian singa: gendang dan bo; masyarakat Cina", "top": "22.6%", "left": "52.7%"}, {"name": "Pentas India: veenai dan talam; tarian bharata natyam", "top": "64.4%", "left": "32.8%"}, {"name": "Pentas Sarawak: sape dan engkerurai; tarian ngajat", "top": "61%", "left": "62%"}, {"name": "Pentas Sabah: kulintangan dan sompoton; tarian sumazau", "top": "51.6%", "left": "71.7%"}], "aftermath": "Pentas tersilap susun. Alat muzik yang salah dibunyikan dan tarian bertukar tempat.", "turns": [{"after": 6, "options": [{"text": "Sebenarnya, alat muzik dan tarian ialah warisan yang membentuk identiti negara kita.", "isCorrect": true, "reaction": "Betul, pakcik. Kami akan menjaganya."}, {"text": "Alat muzik lama tidak perlu dijaga lagi, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Orang tua di barisan hadapan menggeleng kecewa."}, {"text": "Cukuplah alat muzik moden sahaja, jadi cukup dibiarkan begitu sahaja dan biarkan sahaja.", "isCorrect": false, "reaction": "Pemuzik lain tersinggung kerana warisan mereka dipandang rendah."}], "clue": "Warisan membentuk identiti negara."}]}'),
(406, 'e4_n1_s6', 'Bengkel Alat Muzik', 'Padankan alat muzik dengan bahan atau cirinya.', '4', 'Mengenal pasti ciri alat muzik: angklung, gambus, nafiri, geduk, sape dan sompoton.', '{"pairs": [{"text": "Angklung", "pair": 1}, {"text": "Buluh diikat pada rangka yang disebut ancak", "pair": 1}, {"text": "Gambus", "pair": 2}, {"text": "Dibuat daripada kayu keras seperti kayu pokok nangka", "pair": 2}, {"text": "Nafiri", "pair": 3}, {"text": "Diperbuat daripada logam, lazimnya perak", "pair": 3}, {"text": "Geduk", "pair": 4}, {"text": "Gendang dua muka dari belulang lembu atau kerbau", "pair": 4}, {"text": "Sape", "pair": 5}, {"text": "Diperbuat daripada kayu meranti, tali dipetik", "pair": 5}, {"text": "Sompoton", "pair": 6}, {"text": "Buluh dilekatkan pada labu kering dengan lilin kelulut", "pair": 6}], "aftermath": "Bahan tersilap padan dan alat muzik rosak sebelum dimainkan. Murid itu semakin yakin warisan tidak berguna.", "turns": [{"after": 6, "options": [{"text": "Alat lama dibuat daripada bahan alam menunjukkan kebijaksanaan pencipta, jadi wajar dihargai.", "isCorrect": true, "reaction": "Betul, pakcik. Aku mahu belajar membuat angklung."}, {"text": "Alat lama tidak istimewa kerana murah dan tidak payah difikirkan panjang dan lupakan sahaja.", "isCorrect": false, "reaction": "Pemuzik tua terdiam. Kebijaksanaan nenek moyang direndahkan."}, {"text": "Alat lama patut dibuang kerana lama dan tiada siapa yang akan peduli dan itu bukan urusan kita.", "isCorrect": false, "reaction": "Kata-kata itu menyakiti hati orang yang menjaga bengkel ini."}], "clue": "Bahan alam, kebijaksanaan pencipta."}]}'),
(407, 'e4_n1_s7', 'Senarai Tarian Pentas', 'Padankan tarian dengan ciri atau tujuannya.', '4', 'Mengenal pasti tarian makyung, zapin, singa, bharata natyam, ngajat dan sumazau serta tujuannya.', '{"pairs": [{"text": "Makyung", "pair": 1}, {"text": "Seni drama: lakonan, tarian, muzik dan nyanyian", "pair": 1}, {"text": "Zapin", "pair": 2}, {"text": "Hiburan semasa pesta dan majlis perkahwinan", "pair": 2}, {"text": "Tarian singa", "pair": 3}, {"text": "Tahun Baharu Cina, lambang keharmonian", "pair": 3}, {"text": "Bharata natyam", "pair": 4}, {"text": "Pembuka tirai persembahan kebudayaan India", "pair": 4}, {"text": "Ngajat", "pair": 5}, {"text": "Kaum Iban semasa Hari Gawai dan upacara ritual", "pair": 5}, {"text": "Sumazau", "pair": 6}, {"text": "Menghormati semangat padi, Pesta Kaamatan", "pair": 6}], "aftermath": "Senarai tersilap dan penari naik pentas tidak sepadan dengan iringan muzik. Penonton tertanya-tanya dan majlis kelam-kabut.", "turns": [{"after": 6, "options": [{"text": "Bagi aku, setiap tarian ada maksud dan tujuan, jadi iringan muzik mesti betul.", "isCorrect": true, "reaction": "Betul, pakcik. Iringan ngajat memang berbeza."}, {"text": "Menurut aku, tarian hanya hiburan, iringan tidak penting, kerana itu lebih senang.", "isCorrect": false, "reaction": "Penari ngajat kecewa kerana irama bukan irama mereka."}, {"text": "Semua tarian boleh diiringi satu muzik sahaja, lagipun perkara itu tidak penting.", "isCorrect": false, "reaction": "Penonton hairan kerana tarian berbeza tetapi bunyi sama."}], "clue": "Tarian ada makna dan iringan tersendiri."}]}'),
(408, 'e4_n1_s8', 'Kad Tarian Api Unggun', 'Baca kad dan tentukan tarian identiti Orang Asli.', '5', 'Mengenal pasti tarian sewang sebagai identiti masyarakat Orang Asli, dan bhangra sebagai tarian masyarakat Sikh.', '{"clueText": "Kad: Tarian ini menjadi identiti masyarakat Orang Asli. Penari menghias diri dengan selempang bunga-bungaan, daun kelapa, daun palas, daun nipah dan kulit kayu. Alat muziknya ialah buluh centong, gendang, kereb, pensol dan tetawak. Ia untuk upacara ritual, perubatan dan majlis keramaian.", "options": [{"text": "Tarian sewang.", "isCorrect": true}, {"text": "Tarian bhangra.", "isCorrect": false, "consequence": "Bhangra ditarikan oleh masyarakat Sikh dengan dram dhol. Tok Batin mengangkat kening."}, {"text": "Tarian ngajat.", "isCorrect": false, "consequence": "Ngajat ialah tarian kaum Iban di Sarawak. Kau dipandang hairan."}, {"text": "Tarian sumazau.", "isCorrect": false, "consequence": "Sumazau ditarikan kaum Kadazandusun di Sabah. Kad dikembalikan."}], "aftermath": "Kad tersalah baca dan tarian identiti Orang Asli tersilap diperkenalkan. Tok Batin berasa hampa.", "turns": [{"after": 5, "options": [{"text": "Pada pendapat aku, dengan mengenali tarian setiap kaum, kita belajar menghormati cara hidup mereka.", "isCorrect": true, "reaction": "Itu yang kami harapkan, nak."}, {"text": "Tarian Orang Asli tidak penting untuk dipelajari, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Tok Batin menunduk. Kata-kata itu menutup pintu persahabatan."}, {"text": "Tarian setiap kaum sama sahaja, jadi cukup dibiarkan begitu sahaja dan tidak perlu dipedulikan lagi.", "isCorrect": false, "reaction": "Tok Batin menggeleng. Perbezaan itulah keunikan kami."}], "clue": "Kenali tarian untuk menghormati kaum."}]}'),
(409, 'e4_n2_s1', 'Catatan Laci Pertama', 'Baca catatan dan tentukan petempatan dan kegiatan ekonomi masyarakat Melayu dahulu.', '5', 'Mengenal pasti petempatan dan ekonomi Melayu dahulu: kampung, pesisir pantai dan sungai; petani, nelayan, peniaga kecil dan perkhidmatan awam.', '{"clueText": "Catatan: Sebelum merdeka, petempatan penduduk berdasarkan kegiatan ekonomi atau pekerjaan masing-masing. Masyarakat ini tinggal di kampung, persisiran pantai dan sungai, bekerja sebagai petani, nelayan, peniaga kecil-kecilan dan dalam perkhidmatan awam.", "options": [{"text": "Melayu: kampung, pesisir pantai dan sungai; petani, nelayan, peniaga kecil dan perkhidmatan awam.", "isCorrect": true}, {"text": "Melayu: bandar besar; pelombong dan peniaga besar.", "isCorrect": false, "consequence": "Itu gambaran masyarakat Cina. Cucu-cucu menggeleng kepala."}, {"text": "Melayu: ladang getah; pekerja ladang dan pekerja pelabuhan.", "isCorrect": false, "consequence": "Itu kegiatan masyarakat India dahulu. Nenek mengeluh perlahan."}, {"text": "Melayu: pedalaman hutan; pemburu dan pengutip hasil hutan.", "isCorrect": false, "consequence": "Itu kegiatan Orang Asli. Catatan dikembalikan."}], "aftermath": "Catatan tersalah baca dan cucu-cucu menyangka semua orang Melayu dahulu sama pekerjaan.", "turns": [{"after": 6, "options": [{"text": "Petempatan dahulu mengikut sumber, jadi kampung dekat sungai dan pantai.", "isCorrect": true, "reaction": "Betul, nenek. Sekarang kami faham."}, {"text": "Petempatan dahulu dipilih secara rawak, kerana kita tidak rugi apa-apa.", "isCorrect": false, "reaction": "Cucu-cucu keliru kerana tiada sebab di sebalik pilihan itu."}, {"text": "Petempatan dahulu hanya di bandar, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Catatan membuktikan salah. Mereka tinggal di kampung dan tepi sungai."}], "clue": "Petempatan mengikut kegiatan ekonomi."}]}'),
(410, 'e4_n2_s2', 'Dua Laci, Dua Kaum', 'Padankan petempatan dan pekerjaan masyarakat Cina dan India dahulu.', '4', 'Mengenal pasti petempatan dan pekerjaan Cina (pekan dan bandar; pelombong dan peniaga) dan India (ladang dan pinggir bandar; ladang, peniaga kecil, pekerja pelabuhan).', '{"pairs": [{"text": "Cina: tempat tinggal", "pair": 1}, {"text": "Pekan dan bandar", "pair": 1}, {"text": "Cina: pekerjaan", "pair": 2}, {"text": "Pelombong dan peniaga", "pair": 2}, {"text": "India: tempat tinggal", "pair": 3}, {"text": "Ladang dan pinggir bandar", "pair": 3}, {"text": "India: pekerjaan", "pair": 4}, {"text": "Pekerja ladang, peniaga kecil dan pekerja pelabuhan", "pair": 4}], "aftermath": "Laci bertukar isi dan cucu-cucu berselisih tentang cerita datuk mereka sendiri.", "turns": [{"after": 6, "options": [{"text": "Kedua-dua cerita betul kerana setiap kaum mempunyai pekerjaan dan tempat tinggal berbeza.", "isCorrect": true, "reaction": "Nenek bijak. Kami tidak berbalah lagi."}, {"text": "Cerita Ah Meng betul, cerita Kavitha salah, jadi tidak payah difikirkan panjang dan lupakan sahaja.", "isCorrect": false, "reaction": "Kavitha merajuk kerana cerita datuknya dinafikan."}, {"text": "Cerita Kavitha betul, cerita Ah Meng salah, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Ah Meng terdiam dan menunduk malu."}], "clue": "Dua cerita, dua pekerjaan, kedua-duanya benar."}]}'),
(411, 'e4_n2_s3', 'Catatan Laci Ketiga', 'Baca catatan dan tentukan petempatan dan kegiatan Orang Asli dahulu.', '5', 'Mengenal pasti petempatan Orang Asli dahulu: pedalaman, terutama di Perak, Selangor, Pahang, Kelantan dan Terengganu; kraf tangan, berburu dan hasil hutan.', '{"clueText": "Catatan: Masyarakat ini tinggal di pedalaman, terutama di Perak, Selangor, Pahang, Kelantan dan Terengganu. Mereka mengusahakan kegiatan kraf tangan, berburu dan mengutip hasil hutan.", "options": [{"text": "Pedalaman: kraf tangan, berburu dan mengutip hasil hutan.", "isCorrect": true}, {"text": "Bandar: melombong dan berniaga.", "isCorrect": false, "consequence": "Itu kegiatan masyarakat Cina dahulu. Tok Batin senyum nipis."}, {"text": "Ladang: menoreh getah dan bekerja di pelabuhan.", "isCorrect": false, "consequence": "Itu kegiatan India dahulu. Catatan dikembalikan."}, {"text": "Pantai: nelayan dan pembuat perahu sahaja.", "isCorrect": false, "consequence": "Itu gambaran pesisir pantai. Catatan menyebut pedalaman."}], "aftermath": "Catatan disalah baca dan Orang Asli dikatakan duduk di bandar. Tok Batin menggeleng.", "turns": [{"after": 6, "options": [{"text": "Mereka bergantung kepada hutan dan kraf tangan kerana tinggal di pedalaman.", "isCorrect": true, "reaction": "Betul, nenek. Hutan ialah kampung mereka."}, {"text": "Rasanya, mereka bergantung kepada kilang kerana tinggal dekat bandar.", "isCorrect": false, "reaction": "Cucu-cucu ketawa kecil kerana catatan menyebut pedalaman."}, {"text": "Mereka tidak bekerja kerana hasil hutan tidak berharga dan itu lebih senang.", "isCorrect": false, "reaction": "Tok Batin terguris. Hasil hutan ialah rezeki mereka."}], "clue": "Hutan ialah sumber utama mereka."}]}'),
(412, 'e4_n2_s4', 'Peta Kaum Sarawak', 'Padankan kaum di Sarawak dengan petempatan dan kegiatan ekonominya dahulu.', '4', 'Mengenal pasti petempatan dan ekonomi kaum di Sarawak dahulu: pedalaman (Bidayuh, Kenyah, Kelabit), lembah sungai (Iban, Bisaya), pesisir pantai (Melayu, Melanau, Kedayan).', '{"pairs": [{"text": "Bidayuh, Kenyah dan Kelabit", "pair": 1}, {"text": "Pedalaman: padi sawah, padi bukit dan hasil hutan", "pair": 1}, {"text": "Iban dan Bisaya", "pair": 2}, {"text": "Lembah sungai: petani", "pair": 2}, {"text": "Melayu, Melanau dan Kedayan", "pair": 3}, {"text": "Pesisir pantai: pedagang, pembuat perahu, pengusaha sagu", "pair": 3}], "aftermath": "Peta tersilap dan cucu-cucu menyangka semua kaum Sarawak hidup dengan cara yang sama.", "turns": [{"after": 6, "options": [{"text": "Pada pendapat aku, kaum yang berbeza tinggal di tempat berbeza kerana sumber dan pekerjaan mereka berbeza.", "isCorrect": true, "reaction": "Betul, nenek. Kami mengenali jiran sendiri."}, {"text": "Semua kaum Sarawak tinggal di tepi laut, kerana tiada siapa yang akan peduli dan itu bukan urusan kita.", "isCorrect": false, "reaction": "Apai Iban membantah kerana kaumnya di lembah sungai."}, {"text": "Kaum Sarawak tidak mempunyai petempatan tetap, jadi tidak payah difikirkan panjang dan itu lebih senang.", "isCorrect": false, "reaction": "Jenny berkerut dahi kerana kaumnya jelas tinggal di lembah sungai."}], "clue": "Sumber alam menentukan petempatan."}]}'),
(413, 'e4_n2_s5', 'Peta Kaum Sabah', 'Padankan kaum di Sabah dengan petempatan dan kegiatannya dahulu.', '4', 'Mengenal pasti petempatan dan ekonomi kaum di Sabah dahulu: Murut, Kadazandusun, Rungus, Bajau, Melayu Brunei, Iranun dan Suluk.', '{"pairs": [{"text": "Murut", "pair": 1}, {"text": "Pedalaman: petani dan mengutip hasil hutan", "pair": 1}, {"text": "Kadazandusun", "pair": 2}, {"text": "Pedalaman: mengusahakan padi", "pair": 2}, {"text": "Rungus", "pair": 3}, {"text": "Pedalaman: terkenal dalam seni perusahaan kreatif", "pair": 3}, {"text": "Bajau", "pair": 4}, {"text": "Petani atau nelayan", "pair": 4}, {"text": "Melayu Brunei, Iranun, Suluk", "pair": 5}, {"text": "Pesisir pantai: nelayan, pembuat perahu, pedagang", "pair": 5}], "aftermath": "Peta tersilap dan cucu-cucu menyangka semua kaum Sabah menangkap ikan. Pak Bajau menggeleng.", "turns": [{"after": 6, "options": [{"text": "Bajau boleh menjadi petani atau nelayan, dan kaum lain mempunyai kerja mereka sendiri.", "isCorrect": true, "reaction": "Itu betul, nenek. Terima kasih."}, {"text": "Semua kaum Sabah menjadi nelayan, jadi tidak payah difikirkan panjang dan lupakan sahaja.", "isCorrect": false, "reaction": "Linda memprotes kerana kaumnya mengusahakan padi di pedalaman."}, {"text": "Semua kaum Sabah tinggal di bandar, kerana tiada siapa yang akan peduli dan biarkan sahaja.", "isCorrect": false, "reaction": "Pak Bajau tergelak kerana petempatan dahulu bukan di bandar."}], "clue": "Setiap kaum mempunyai kegiatan sendiri."}]}'),
(414, 'e4_n2_s6', 'Dari Berasingan kepada Bersama', 'Susun perubahan petempatan dan ekonomi daripada dahulu hingga kini.', '1', 'Memahami perubahan: dahulu petempatan ikut ekonomi; selepas merdeka dan pembentukan Malaysia pemimpin merancang dasar; kini tiada pengasingan tempat tinggal.', '{"timelineItems": [{"id": 1, "year": "Sebelum merdeka", "text": "Petempatan penduduk berdasarkan kegiatan ekonomi atau pekerjaan masing-masing", "why": "Pengasingan tempat tinggal berlaku mengikut pekerjaan."}, {"id": 2, "year": "Selepas merdeka", "text": "Negara semakin makmur dan pemimpin merancang pelbagai dasar pembangunan", "why": "Pemimpin mula merancang dasar untuk mengurangkan jurang."}, {"id": 3, "year": "Seterusnya", "text": "Usaha menangani kegiatan ekonomi berasaskan kaum menampakkan kejayaan", "why": "Dasar yang dirancang membawa hasil."}, {"id": 4, "year": "Kini", "text": "Rakyat bekerja bersama dan tinggal dalam satu kawasan perumahan tanpa pemisahan", "why": "Toleransi dan kemakmuran membolehkan semua hidup bersama."}], "aftermath": "Susunan tersilap dan cucu menyangka petempatan berasingan masih berlaku hari ini.", "turns": [{"after": 6, "options": [{"text": "Sikap toleransi dan kemakmuran membolehkan kita hidup bersama dalam satu kawasan.", "isCorrect": true, "reaction": "Itu jawapan yang membuat nenek tersenyum."}, {"text": "Kerana semua orang dipaksa berpindah, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Cucu-cucu berasa tidak adil. Tiada catatan paksaan itu."}, {"text": "Kerana semua orang bekerja sama jenis kerja, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Itu tidak betul, Kini rakyat bekerja dalam pelbagai sektor."}], "clue": "Toleransi dan kemakmuran menyatukan rakyat."}]}'),
(415, 'e4_n2_s7', 'Helah Si Luncai', 'Susun kejadian cerita Si Luncai dengan Labu-labunya mengikut urutan.', '1', 'Memahami jalan cerita Si Luncai dengan Labu-labunya dan iktibar jangan mempersendakan orang lain.', '{"timelineItems": [{"id": 1, "year": "Mula-mula", "text": "Si Luncai dihukum raja kerana mempermain-mainkan raja dan pembesar", "why": "Itulah punca hukumannya."}, {"id": 2, "year": "Kemudian", "text": "Pesuruh raja memasukkan Si Luncai ke dalam guni dan membawanya dengan perahu ke tengah laut", "why": "Hukuman mula dijalankan."}, {"id": 3, "year": "Seterusnya", "text": "Si Luncai menyanyikan lagu Si Luncai terjun dengan labu-labunya sehingga pesuruh raja leka", "why": "Helahnya menghilangkan perhatian pesuruh."}, {"id": 4, "year": "Akhirnya", "text": "Si Luncai terjun dengan labu air dan pesuruh raja mencampakkan guni berisi labu", "why": "Si Luncai selamat sampai ke pantai."}], "aftermath": "Susunan tersilap dan cerita menjadi kelucuan sahaja, tanpa iktibar yang jelas.", "turns": [{"after": 6, "options": [{"text": "Si Luncai bijak kerana boleh memperdaya pesuruh raja, tetapi iktibarnya jangan mempersendakan orang lain.", "isCorrect": true, "reaction": "Betul, nenek. Kami faham iktibarnya."}, {"text": "Si Luncai patut ditiru kerana suka mempermain-mainkan orang dan tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Nenek mengerut dahi. Itu bukan pengajaran yang betul."}, {"text": "Si Luncai tidak bijak sama sekali, jadi cukup dibiarkan begitu sahaja dan kita tidak perlu ambil kisah.", "isCorrect": false, "reaction": "Cucu-cucu bertanya semula kerana beliau berjaya terlepas."}], "clue": "Bijak, tetapi jangan mempersendakan orang lain."}]}'),
(416, 'e4_n2_s8', 'Kad Legenda Santubong', 'Padankan watak dan perkara dalam legenda Santubong Sang Puteri.', '4', 'Memahami legenda Santubong: Puteri Santubong menenun, Puteri Sejinjang menumbuk padi, Putera Serapi dari Matang, dan iktibar jangan bertengkar sesama sendiri.', '{"pairs": [{"text": "Puteri Santubong", "pair": 1}, {"text": "Pandai menenun kain", "pair": 1}, {"text": "Puteri Sejinjang", "pair": 2}, {"text": "Mahir menumbuk padi", "pair": 2}, {"text": "Putera Serapi", "pair": 3}, {"text": "Pemuda dari Matang yang disukai kedua-dua puteri", "pair": 3}, {"text": "Pasir Kuning dan Pasir Putih", "pair": 4}, {"text": "Dua kampung berjiran yang didamaikan", "pair": 4}, {"text": "Akibat melanggar sumpah", "pair": 5}, {"text": "Kedua-dua puteri bertukar menjadi gunung", "pair": 5}], "aftermath": "Kad bertukar dan legenda disalah ceritakan. Cucu-cucu menyangka kedua-dua puteri bersahabat sehingga akhir.", "turns": [{"after": 6, "options": [{"text": "Sebenarnya, mereka bertukar menjadi gunung kerana bergaduh dan melanggar syarat.", "isCorrect": true, "reaction": "Betul, nenek. Iktibarnya jangan bertengkar sesama sendiri."}, {"text": "Mereka bertukar menjadi gunung kerana berjaya berdamai dan kita tidak rugi apa-apa.", "isCorrect": false, "reaction": "Cucu-cucu keliru. Mereka dikenakan padah kerana bergaduh."}, {"text": "Pada pendapat aku, mereka bertukar menjadi gunung kerana memakmurkan kampung.", "isCorrect": false, "reaction": "Mereka memang memakmurkan kampung, tetapi bukan itu sebab menjadi gunung."}], "clue": "Padah kerana bergaduh sesama sendiri."}]}'),
(417, 'e4_n3_s1', 'Cari Lima Permainan di Gelanggang', 'Cari lima petunjuk permainan anjung, laman dan kawasan lapang.', '2', 'Mengenal pasti jenis permainan tradisional: anjung, laman dan kawasan lapang.', '{"bgImage": "../assets/gameAsset/background/permainan_tradisional.png", "hotspots": [{"name": "Permainan anjung: congkak, batu seremban, go dan chaturangam", "top": "28%", "left": "15%"}, {"name": "Permainan laman: sepak raga", "top": "47.8%", "left": "45.7%"}, {"name": "Permainan lapang: wau di langit", "top": "7.2%", "left": "63.2%"}, {"name": "Permainan lapang: gasing dan tibau", "top": "46.3%", "left": "62.7%"}, {"name": "Permainan laman: chap teh dan kabaddi", "top": "61.4%", "left": "59.8%"}], "aftermath": "Petunjuk hilang dan permainan dimainkan di tempat tidak sesuai. Sepak raga terbang ke atas anjung.", "turns": [{"after": 6, "options": [{"text": "Permainan tradisional ada tiga jenis supaya sesuai dengan ruang dan alat.", "isCorrect": true, "reaction": "Betul, Tok. Sekarang kami boleh bermain dengan betul."}, {"text": "Menurut aku, semua permainan dimainkan di satu tempat sahaja, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Gelanggang menjadi sempit dan kanak-kanak berlanggar."}, {"text": "Pada pendapat aku, permainan tradisional tidak mempunyai jenis, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Kanak-kanak lain mengangkat kening kerana ada tiga jenis yang jelas."}], "clue": "Tiga jenis permainan."}]}'),
(418, 'e4_n3_s2', 'Nama dan Cara Bermain', 'Padankan permainan tradisional dengan cara bermainnya.', '4', 'Mengenal pasti ciri congkak, batu seremban, go, kabaddi, chap teh dan sepak raga.', '{"pairs": [{"text": "Congkak", "pair": 1}, {"text": "Mengisi buah ke dalam lubang pada papan congkak", "pair": 1}, {"text": "Batu seremban", "pair": 2}, {"text": "Lima atau tujuh biji batu kecil dilambung dan disambut", "pair": 2}, {"text": "Go atau Weiqi", "pair": 3}, {"text": "Buah hitam dan putih, menguasai kawasan papan yang lebih besar", "pair": 3}, {"text": "Kabaddi", "pair": 4}, {"text": "Dua pasukan, tujuh pemain, menyentuh pihak lawan", "pair": 4}, {"text": "Chap teh", "pair": 5}, {"text": "Bola lawi bulu ayam ditating, juga dipanggil tating lawi", "pair": 5}, {"text": "Sepak raga", "pair": 6}, {"text": "Bola rotan ditimang dengan kaki, sejak zaman Kesultanan Melayu Melaka", "pair": 6}], "aftermath": "Padanan tersilap dan permainan dimainkan dengan cara yang salah. Gelanggang menjadi riuh dan kecoh.", "turns": [{"after": 6, "options": [{"text": "Setiap permainan ada cara bermain sendiri, jadi kita perlu mengenalinya sebelum bermain.", "isCorrect": true, "reaction": "Betul, Tok. Kami tidak berbalah lagi."}, {"text": "Pada pendapat aku, semua permainan sama sahaja kerana semuanya hiburan dan biarkan sahaja.", "isCorrect": false, "reaction": "Kanak-kanak membantah kerana alat dan caranya berbeza."}, {"text": "Cara bermain tidak penting asalkan menang, jadi tidak payah difikirkan panjang dan itu lebih senang.", "isCorrect": false, "reaction": "Permainan menjadi kecoh dan sesetengah kanak-kanak merajuk."}], "clue": "Setiap permainan ada cara tersendiri."}]}'),
(419, 'e4_n3_s3', 'Empat Permainan Lapang', 'Padankan permainan kawasan lapang dengan ciri atau tempatnya.', '4', 'Mengenal pasti permainan kawasan lapang: wau, tibau, sepak manggis dan gasing.', '{"pairs": [{"text": "Wau", "pair": 1}, {"text": "Lazimnya dimainkan selepas musim menuai", "pair": 1}, {"text": "Tibau", "pair": 2}, {"text": "Pesta Kaul oleh masyarakat Melanau, Sarawak", "pair": 2}, {"text": "Sepak manggis", "pair": 3}, {"text": "Majlis keramaian di Kota Belud, Sabah, sepak bola ke hadiah", "pair": 3}, {"text": "Gasing", "pair": 4}, {"text": "Gasing uri dan gasing pangkah", "pair": 4}], "aftermath": "Kad tersilap dan kanak-kanak bermain di acara yang salah. Pesta berlangsung dalam kekeliruan.", "turns": [{"after": 6, "options": [{"text": "Rasanya, permainan lapang dimainkan di padang kerana memerlukan ruang yang luas.", "isCorrect": true, "reaction": "Betul, Tok. Wau tidak boleh terbang di anjung."}, {"text": "Permainan lapang boleh dimainkan di dalam bilik, lagipun perkara itu tidak penting.", "isCorrect": false, "reaction": "Wau tersangkut di langit-langit dan kanak-kanak ketawa."}, {"text": "Permainan lapang tidak memerlukan ruang, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Gasing mengenai kaki kawan-kawan kerana ruang sempit."}], "clue": "Permainan lapang perlukan ruang luas."}]}'),
(420, 'e4_n3_s4', 'Kad Catur Peperangan', 'Baca kad dan tentukan permainan yang menyerupai catur dan melambangkan peperangan.', '5', 'Mengenal pasti chaturangam sebagai permainan seperti catur, simulasi peperangan, dan paramapadham seperti dam ular.', '{"clueText": "Kad: Permainan ini dimainkan oleh dua orang pemain, umpama simulasi peperangan bagi memperlihatkan kekuatan tentera. Kemenangan bergantung pada kejayaan menakluk lawan, terutamanya menewaskan raja.", "options": [{"text": "Chaturangam.", "isCorrect": true}, {"text": "Paramapadham.", "isCorrect": false, "consequence": "Paramapadham seperti dam ular dan menggunakan dadu. Kad dikembalikan."}, {"text": "Congkak.", "isCorrect": false, "consequence": "Congkak menggunakan papan berlubang, bukan raja dan tentera. Kanak-kanak ketawa."}, {"text": "Yoyo Cina.", "isCorrect": false, "consequence": "Yoyo Cina dimainkan secara perseorangan. Kad dikembalikan."}], "aftermath": "Kad tersalah baca dan kanak-kanak menyangka paramapadham menewaskan raja. Permainan jadi huru-hara.", "turns": [{"after": 6, "options": [{"text": "Permainan dari pelbagai budaya dimainkan bersama di negara kita, dan itu memupuk toleransi.", "isCorrect": true, "reaction": "Betul, Tok. Kami main semua permainan sekarang."}, {"text": "Permainan luar tidak patut dimainkan di sini, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Kanak-kanak kecewa kerana mahu bermain dengan semua kawan."}, {"text": "Permainan dari luar lebih baik daripada permainan kita, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Kanak-kanak tempatan terguris dan perbalahan bermula."}], "clue": "Pelbagai permainan menyatukan kanak-kanak."}]}'),
(421, 'e4_n3_s5', 'Papan Warisan Kebangsaan', 'Baca papan kenyataan dan tentukan permainan yang diangkat sebagai warisan kebangsaan.', '5', 'Mengenal pasti permainan warisan kebangsaan: congkak, batu seremban, kabaddi, tating lawi, menyumpit, pistol buluh, sepak raga, ketinting, baling tin dan ketuk keli.', '{"clueText": "Papan kenyataan: Congkak, batu seremban, kabaddi, tating lawi, menyumpit, pistol buluh, sepak raga, ketinting, baling tin dan ketuk keli telah diangkat sebagai warisan kebangsaan negara.", "options": [{"text": "Congkak dan sepak raga.", "isCorrect": true}, {"text": "Bola sepak dan badminton.", "isCorrect": false, "consequence": "Itu sukan moden yang tiada dalam senarai warisan. Papan menunjukkan permainan tradisional."}, {"text": "Boling dan tenis.", "isCorrect": false, "consequence": "Itu sukan moden. Kanak-kanak menggeleng."}, {"text": "Permainan komputer.", "isCorrect": false, "consequence": "Permainan komputer bukan permainan tradisional warisan kebangsaan."}], "aftermath": "Papan tersilap baca dan permainan moden dikatakan warisan kebangsaan. Kanak-kanak keliru.", "turns": [{"after": 6, "options": [{"text": "Permainan tradisional diangkat sebagai warisan supaya generasi akan datang terus memainkannya.", "isCorrect": true, "reaction": "Betul, Tok. Kami mahu mengajar adik-adik."}, {"text": "Aku fikir permainan tradisional tidak perlu dikekalkan, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Tok menarik muka masam. Warisan akan hilang tanpa usaha kita."}, {"text": "Pada pendapat aku, permainan tradisional hanya untuk orang tua, jadi kita tidak perlu ambil kisah.", "isCorrect": false, "reaction": "Kanak-kanak ketawa kerana mereka sendiri suka bermain."}], "clue": "Kekalkan permainan tradisional untuk generasi akan datang."}]}'),
(422, 'e4_n3_s6', 'Cari Petunjuk Nunuk Ragang', 'Cari tiga petunjuk dalam legenda Nunuk Ragang.', '2', 'Memahami legenda Nunuk Ragang: kemunculan pelbagai kaum di Tambunan dan Ranau, ayam gergasi, pohon nunuk dan Sungai Liwagu.', '{"bgImage": "../assets/gameAsset/background/nunuk_ragang.png", "hotspots": [{"name": "Pohon nunuk: tempat penduduk Sungai Liwagu berehat", "top": "52.5%", "left": "40.1%"}, {"name": "Sungai Liwagu: tempat asal penduduk sebelum terbang dan berpecah", "top": "80.4%", "left": "86.7%"}, {"name": "Ayam gergasi merah bertaji emas yang mengibar sayap", "top": "35.5%", "left": "46.6%"}], "aftermath": "Petunjuk tidak ditemui dan asal usul pelbagai kaum Sabah terus kabur.", "turns": [{"after": 6, "options": [{"text": "Rasanya, legenda ini menggambarkan asal usul pelbagai kaum Sabah dan mengajar kita menghargai keturunan.", "isCorrect": true, "reaction": "Betul, Tok. Kami bangga dengan asal usul kami."}, {"text": "Rasanya, legenda ini hanya cerita khayalan, tidak penting, kerana tiada siapa yang akan peduli dan biarkan sahaja.", "isCorrect": false, "reaction": "Linda berasa asal usul kaumnya dipandang remeh."}, {"text": "Pada pendapat aku, legenda ini bercerita tentang kemunculan kaum Iban, kerana ramai orang buat begitu.", "isCorrect": false, "reaction": "Pak Bajau membetulkan kerana cerita ini tentang kaum di Tambunan dan Ranau."}], "clue": "Hargai asal usul keturunan."}]}'),
(423, 'e4_n3_s7', 'Kad Asas Perpaduan', 'Baca kad dan tentukan kepentingan bertoleransi antara kaum sebagai asas perpaduan.', '5', 'Memahami kepentingan bertoleransi: tiada pergaduhan, mengekalkan keharmonian dan kesejahteraan, mengukuhkan patriotisme, mengelakkan salah faham.', '{"clueText": "Kad: Sikap bertoleransi memastikan tidak berlakunya pergaduhan. Ia mengekalkan keharmonian dan kesejahteraan negara, mengukuhkan semangat patriotisme dalam diri, dan mengelakkan salah faham antara kaum.", "options": [{"text": "Mengekalkan keharmonian dan mengelakkan salah faham antara kaum.", "isCorrect": true}, {"text": "Menambah salah faham supaya orang berhati-hati.", "isCorrect": false, "consequence": "Kanak-kanak ketawa. Jawapan itu bertentangan dengan kad."}, {"text": "Mengasingkan kaum supaya tidak berjumpa.", "isCorrect": false, "consequence": "Perpisahan menambah curiga dan menjauhkan kawan."}, {"text": "Memastikan satu kaum sahaja yang menentukan peraturan.", "isCorrect": false, "consequence": "Kanak-kanak lain membantah kerana mereka tidak didengari."}], "aftermath": "Kad tersalah baca dan kanak-kanak terus berbalah. Permainan terhenti dan taman menjadi sunyi.", "turns": [{"after": 6, "options": [{"text": "Kita bertanya dan bertoleransi, kerana tidak semua yang kita tidak faham itu ejekan.", "isCorrect": true, "reaction": "Itu jawapan yang matang, Tok. Mereka bersalam."}, {"text": "Rasanya, kita balas ejekan dengan ejekan, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Perbalahan menjadi pergaduhan dan kanak-kanak menangis."}, {"text": "Kita larang mereka bercakap bahasa sendiri, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Larangan itu menyinggung perasaan dan mengundang bantahan."}], "clue": "Bertanya dan bertoleransi."}]}'),
(424, 'e4_n3_s8', 'Kepentingan Keunikan Budaya', 'Padankan perkara dengan kepentingannya.', '4', 'Memahami kepentingan menghargai keunikan budaya tempatan dan berkongsi maklumat tentang kepelbagaian kaum.', '{"pairs": [{"text": "Keunikan seni warisan", "pair": 1}, {"text": "Menjadi tumpuan pelancong dari luar negara", "pair": 1}, {"text": "Keunikan seni tradisional", "pair": 2}, {"text": "Memupuk semangat patriotisme dalam diri rakyat", "pair": 2}, {"text": "Keunikan budaya tempatan", "pair": 3}, {"text": "Warisan negara yang perlu dipelihara", "pair": 3}, {"text": "Berkongsi maklumat kaum", "pair": 4}, {"text": "Memupuk persefahaman antara pelbagai kaum", "pair": 4}, {"text": "Sikap hormat-menghormati", "pair": 5}, {"text": "Mengeratkan perpaduan antara kaum", "pair": 5}], "aftermath": "Padanan tersilap dan murid yakin budaya tidak penting. Pelancong hanya mengambil gambar lalu pergi tanpa memahami.", "turns": [{"after": 6, "options": [{"text": "Keunikan budaya kita menjadi warisan dan menarik pelancong, jadi wajar dijaga.", "isCorrect": true, "reaction": "Betul, Tok. Aku akan berkongsi dengan kawan-kawan."}, {"text": "Sebenarnya, budaya lama menyusahkan dan tidak perlu dijaga, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Murid lain terdiam kerana tidak setuju."}, {"text": "Aku fikir budaya hanya penting untuk orang tua, lagipun perkara itu tidak penting.", "isCorrect": false, "reaction": "Tok tersenyum pahit. Anak muda juga pewaris budaya."}], "clue": "Jaga budaya sebagai warisan."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e4_n1_s1', 'hint', 'Ingat Serani menuturkan Kristang, dan Baba Nyonya dengan Melayu Baba.', NULL, NULL),
(401, NULL, 'hint', 'Setiap kaum ada bahasanya. Sikh dengan Punjabi, Serani dengan Kristang. Selebihnya kau sudah dengar tadi.', 'Malam itu aku belajar bahawa setiap kaum ada bahasanya sendiri. Orang Cina bertutur Mandarin, Hokkien, Hakka dan Kantonis, orang India bertutur Tamil, Telugu dan Malayalam, orang Sikh bertutur Punjabi, kaum Serani bertutur Kristang dan Inggeris, dan Baba Nyonya memakai Melayu Baba.', 'Betul! Pengacara membaca kad itu dengan yakin dan penonton tersenyum apabila mendengar bahasa mereka disebut.'),
(NULL, 'e4_n1_s2', 'hint', 'Iban, Bidayuh dan Melanau ialah kaum di Sarawak, bukan di sini.', NULL, NULL),
(402, NULL, 'hint', 'Tok Batin menyebut satu nama yang berbunyi Semang. Dua lagi bermula dengan S dan M.', 'Tok Batin mengajarku bahawa Orang Asli di Semenanjung terbahagi kepada tiga kumpulan terbesar, iaitu Negrito (Semang), Senoi dan Melayu Proto. Mereka bangga kerana masih memelihara kraf tangan, ubat herba dan bahasa suku masing-masing.', 'Syabas! Tok Batin tersenyum puas. Budak bandar itu menulis tiga nama itu di tapak tangannya supaya tidak lupa.'),
(NULL, 'e4_n1_s3', 'hint', 'Chetti berkait dengan pedagang India, Baba Nyonya dengan pedagang China.', NULL, NULL),
(403, NULL, 'hint', 'Tiga kaum lahir daripada perkahwinan pedagang. Satu lagi menyambut Songkran, dan satu lagi memakai sarban.', 'Di pasar malam Melaka aku mengenali kaum peranakan. Baba dan Nyonya serta Chetti lahir daripada perkahwinan pedagang China dan India dengan penduduk tempatan, kaum Serani ialah orang Eurasia dengan tarian branyo dan frapeirra, dan kaum Siam menyambut Songkran di wat.', 'Hebat! Empat kad dipadankan dan penjual kuih berhenti seketika untuk bertepuk tangan.'),
(NULL, 'e4_n1_s4', 'hint', 'Bidayuh dan Bajau bukan kaum terbesar di negeri masing-masing.', NULL, NULL),
(404, NULL, 'hint', 'Satu kaum terbesar di Sarawak bertutur bahasa Iban. Satu lagi di Sabah bernama Kadazandusun.', 'Aku mencatat dua kaum terbesar. Kaum Iban ialah kaum terbesar di Sarawak dengan pua kumbu dan Hari Gawai, manakala kaum Kadazandusun ialah kaum terbesar di Sabah dengan Pesta Kaamatan. Kedua-duanya wajar dihargai.', 'Tepat! Apai Iban dan Linda berjabat tangan di hadapan semua pengunjung, tidak lagi berebut siapa yang lebih besar.'),
(NULL, 'e4_n1_s5', 'hint', 'Tiga sudut di Semenanjung dan dua di Borneo.', NULL, NULL),
(405, NULL, 'hint', 'Lima sudut, iaitu Melayu, Cina, India, Sarawak dan Sabah. Lihat alat muzik dan penari di setiap sudut.', 'Pentas malam itu ada lima sudut. Melayu dengan gambus, angklung, makyung dan zapin, Cina dengan gendang, bo dan tarian singa, India dengan veenai, talam dan bharata natyam, Sarawak dengan sape, engkerurai dan ngajat, Sabah dengan kulintangan, sompoton dan sumazau.', 'Berjaya! Papan petunjuk berdiri semula dan setiap pasukan menuju ke sudut masing-masing sambil tersenyum.'),
(NULL, 'e4_n1_s6', 'hint', 'Gendang dua muka itu geduk. Alat daripada logam perak itu nafiri.', NULL, NULL),
(406, NULL, 'hint', 'Buluh, kayu, logam dan kulit haiwan. Angklung dan sompoton sama-sama dari buluh, tetapi tidak sama rangkanya.', 'Di bengkel itu aku tahu bahawa angklung diperbuat daripada buluh pada rangka ancak, gambus daripada kayu nangka, nafiri daripada logam perak, geduk daripada belulang lembu atau kerbau, sape daripada kayu meranti dan sompoton daripada buluh dengan labu kering. Semuanya mengambil bahan alam.', 'Hebat! Murid itu terdiam memegang sompoton. Katanya, alat sekecil itu rupanya ada rahsia di dalamnya.'),
(NULL, 'e4_n1_s7', 'hint', 'Ngajat dengan Hari Gawai, sumazau dengan semangat padi.', NULL, NULL),
(407, NULL, 'hint', 'Satu tarian membuka tirai, satu lagi untuk Hari Gawai, dan satu lagi menghormati semangat padi.', 'Aku mencatat tujuan setiap tarian. Makyung ialah seni drama, zapin ialah hiburan pesta dan perkahwinan, tarian singa untuk Tahun Baharu Cina, bharata natyam membuka tirai persembahan India, ngajat untuk Hari Gawai dan sumazau menghormati semangat padi.', 'Tepat! Senarai tarian tersusun semula. Penari-penari berbaris di belakang tirai dengan wajah lega.'),
(NULL, 'e4_n1_s8', 'hint', 'Bhangra ialah tarian Sikh dengan dram dhol.', NULL, NULL),
(408, NULL, 'hint', 'Selempang bunga, daun kelapa dan kulit kayu. Ritual dan perubatan. Bukan tarian dram dhol.', 'Tok Batin menunjukkan tarian sewang. Penarinya memakai selempang bunga, daun kelapa, daun palas, daun nipah dan kulit kayu, diiringi buluh centong, gendang, kereb, pensol dan tetawak untuk ritual, perubatan dan keramaian. Bhangra pula tarian Sikh dengan dram dhol.', 'Syabas! Tok Batin mengangguk perlahan. Api unggun menyala lebih terang apabila tarian sewang bermula.'),
(NULL, 'e4_n2_s1', 'hint', 'Itu gambaran orang Cina atau Orang Asli. Orang Melayu tinggal di kampung, pesisir pantai dan tepi sungai.', NULL, NULL),
(409, NULL, 'hint', 'Orang Melayu dahulu dekat dengan air. Mereka bukan hanya menanam padi.', 'Laci pertama mengajarku bahawa sebelum merdeka petempatan mengikut pekerjaan. Orang Melayu tinggal di kampung, pesisir pantai dan sungai, bekerja sebagai petani, nelayan, peniaga kecil dan dalam perkhidmatan awam.', 'Tepat! Nenek tersenyum bangga. Gambar kampung tepi sungai dalam laci itu kelihatan seakan-akan hidup.'),
(NULL, 'e4_n2_s2', 'hint', 'Pelombong dan peniaga di pekan. Pekerja ladang di ladang.', NULL, NULL),
(410, NULL, 'hint', 'Satu kaum di pekan dan bandar. Satu lagi di ladang dan pinggir bandar.', 'Aku mendengar dua cerita yang kedua-duanya benar. Orang Cina dahulu tinggal di pekan dan bandar sebagai pelombong dan peniaga, manakala orang India tinggal di ladang dan pinggir bandar sebagai pekerja ladang, peniaga kecil dan pekerja pelabuhan.', 'Cemerlang! Ah Meng dan Kavitha tergelak apabila menyedari datuk mereka tidak pernah bertemu.'),
(NULL, 'e4_n2_s3', 'hint', 'Melombong dan berniaga ialah kerja orang Cina di bandar.', NULL, NULL),
(411, NULL, 'hint', 'Mereka tinggal di tempat jauh dari bandar. Hutan memberi segalanya.', 'Orang Asli dahulu tinggal di pedalaman, terutama di Perak, Selangor, Pahang, Kelantan dan Terengganu. Mereka mengusahakan kraf tangan, berburu dan mengutip hasil hutan.', 'Tepat! Tok Batin menunjukkan anyaman rotan kepada cucu-cucu yang terpegun.'),
(NULL, 'e4_n2_s4', 'hint', 'Padi bukit di pedalaman, sagu di pantai.', NULL, NULL),
(412, NULL, 'hint', 'Sungai, pedalaman dan pantai. Setiap kaum dekat dengan sumber hidupnya.', 'Peta Sarawak menunjukkan kaum Bidayuh, Kenyah dan Kelabit di pedalaman dengan padi sawah, padi bukit dan hasil hutan, kaum Iban dan Bisaya di lembah sungai sebagai petani, dan kaum Melayu, Melanau dan Kedayan di pesisir pantai sebagai pedagang, pembuat perahu dan pengusaha sagu.', 'Betul! Jenny dan Apai Iban berpuas hati. Peta Sarawak akhirnya bercerita dengan jujur.'),
(NULL, 'e4_n2_s5', 'hint', 'Murut dan Rungus di pedalaman. Iranun dan Suluk di pantai.', NULL, NULL),
(413, NULL, 'hint', 'Pedalaman dan pantai. Satu kaum petani atau nelayan, satu lagi terkenal dengan seni kreatif.', 'Aku mengenali kaum di Sabah. Murut petani dan pengutip hasil hutan, Kadazandusun menanam padi, Rungus terkenal dengan seni perusahaan kreatif, Bajau petani atau nelayan, dan Melayu Brunei, Iranun serta Suluk nelayan, pembuat perahu dan pedagang di pesisir pantai.', 'Hebat! Linda dan Pak Bajau tersenyum melihat peta Sabah yang kini lengkap.'),
(NULL, 'e4_n2_s6', 'hint', 'Pekerjaan berasingan dahulu, makmur dan toleransi kemudian.', NULL, NULL),
(414, NULL, 'hint', 'Mulakan dengan zaman sebelum merdeka. Selepas merdeka barulah negara makmur dan kaum hidup bersama.', 'Nenek menjelaskan bahawa sebelum merdeka penduduk tinggal mengikut pekerjaan. Selepas merdeka, negara makmur, pemimpin merancang dasar pembangunan, kegiatan ekonomi berasaskan kaum berjaya diatasi, dan sikap toleransi membolehkan rakyat tinggal dalam satu kawasan perumahan.', 'Tepat! Nenek mengangguk dan jiran-jiran taman perumahan itu bertepuk tangan sambil berkongsi kuih.'),
(NULL, 'e4_n2_s7', 'hint', 'Si Luncai dihukum dahulu, baru dibawa ke laut.', NULL, NULL),
(415, NULL, 'hint', 'Mulanya dihukum, kemudian dibawa ke laut, lalu dia menyanyi, dan akhirnya terlepas.', 'Si Luncai dihukum kerana mempermain-mainkan raja, dimasukkan ke dalam guni dan dibawa ke tengah laut, lalu menyanyikan lagunya sehingga pesuruh raja lalai dan dia terlepas dengan labu-labunya. Iktibarnya, jangan mempersendakan orang lain.', 'Hebat! Susunan kejadian betul. Si Luncai ketawa kecil sambil mengayuh labu-labunya menjauhi perahu.'),
(NULL, 'e4_n2_s8', 'hint', 'Akibat melanggar sumpah mereka menjadi gunung.', NULL, NULL),
(416, NULL, 'hint', 'Satu puteri menenun, satu lagi menumbuk padi. Putera dari Matang disukai kedua-duanya.', 'Dalam legenda Santubong, Puteri Santubong pandai menenun kain dan Puteri Sejinjang mahir menumbuk padi. Putera Serapi dari Matang disukai kedua-duanya. Kerana bergaduh dan melanggar syarat, mereka bertukar menjadi gunung. Iktibarnya, jangan bertengkar sesama sendiri.', 'Tepat! Kilat menyambar di luar tingkap seolah-olah legenda itu mengangguk setuju.'),
(NULL, 'e4_n3_s1', 'hint', 'Wau di langit, jadi di kawasan lapang.', NULL, NULL),
(417, NULL, 'hint', 'Anjung, laman dan lapang. Lihat di rumah, di halaman dan di padang.', 'Aku tahu permainan tradisional ada tiga jenis. Congkak, batu seremban, go dan chaturangam ialah permainan anjung, sepak raga ialah permainan laman, manakala wau, gasing dan tibau ialah permainan kawasan lapang.', 'Betul! Kanak-kanak berlari ke tempat permainan masing-masing sambil ketawa.'),
(NULL, 'e4_n3_s2', 'hint', 'Go menggunakan buah hitam dan putih. Congkak menggunakan lubang pada papan.', NULL, NULL),
(418, NULL, 'hint', 'Lubang pada papan, lima atau tujuh batu, buah hitam dan putih, dua pasukan tujuh pemain.', 'Congkak dimainkan dengan mengisi buah ke dalam lubang, batu seremban dengan lima atau tujuh batu yang dilambung dan disambut, Go dengan buah hitam dan putih, kabaddi oleh dua pasukan tujuh pemain, dan chap teh ditating dengan bola lawi bulu ayam.', 'Tepat! Kanak-kanak yang bergaduh tadi kini duduk bersila dan mengajar satu sama lain.'),
(NULL, 'e4_n3_s3', 'hint', 'Dua jenis gasing, iaitu uri dan pangkah.', NULL, NULL),
(419, NULL, 'hint', 'Wau selepas menuai, tibau semasa Pesta Kaul, sepak manggis di Kota Belud.', 'Permainan kawasan lapang termasuk wau yang lazimnya dimainkan selepas musim menuai, tibau semasa Pesta Kaul oleh masyarakat Melanau di Sarawak, sepak manggis di Kota Belud, Sabah, dan gasing uri serta gasing pangkah.', 'Hebat! Wau naik ke langit dan gasing berputar serentak apabila kanak-kanak bersorak.'),
(NULL, 'e4_n3_s4', 'hint', 'Paramapadham seperti dam ular dan memakai dadu.', NULL, NULL),
(420, NULL, 'hint', 'Dua pemain, simulasi peperangan, matlamatnya menewaskan raja. Bukan permainan dadu.', 'Aku belajar bahawa chaturangam ialah permainan dua pemain yang seperti simulasi peperangan, dan kemenangan datang apabila raja lawan ditewaskan. Paramapadham seperti dam ular dan menggunakan dadu. Permainan di negara kita ada unsur dari Timur Tengah, China, India dan Alam Melayu.', 'Tepat! Ah Meng dan Kavitha mula bermain catur bersama di hujung meja.'),
(NULL, 'e4_n3_s5', 'hint', 'Itu sukan moden yang tiada dalam senarai warisan.', NULL, NULL),
(421, NULL, 'hint', 'Bola sepak dan badminton ialah sukan moden. Cari permainan lama pada papan.', 'Papan kenyataan menyenaraikan permainan warisan kebangsaan, iaitu congkak, batu seremban, kabaddi, tating lawi, menyumpit, pistol buluh, sepak raga, ketinting, baling tin dan ketuk keli. Sukan moden seperti bola sepak dan badminton tiada dalam senarai itu.', 'Betul! Tok Permainan menepuk bahu murid itu. Papan warisan kini lebih bermakna kepadanya.'),
(NULL, 'e4_n3_s6', 'hint', 'Bukan kaum Iban. Ini kisah kaum di Tambunan dan Ranau.', NULL, NULL),
(422, NULL, 'hint', 'Pohon, sungai dan seekor burung besar berwarna merah.', 'Legenda Nunuk Ragang bermula di tepi Sungai Liwagu. Penduduk berehat di bawah pohon nunuk, seekor ayam gergasi merah bertaji emas mengibar sayap, lalu penduduk berpecah ke Tambunan dan Ranau dan membina dialek masing-masing. Iktibarnya, hargailah asal usul keturunan.', 'Cemerlang! Tiga petunjuk ditemui. Linda memandang pohon itu lama dan berbisik terima kasih.'),
(NULL, 'e4_n3_s7', 'hint', 'Toleransi mengelakkan salah faham dan menjaga keharmonian.', NULL, NULL),
(423, NULL, 'hint', 'Tiada pergaduhan, harmoni, patriotisme dan tiada salah faham.', 'Toleransi antara kaum ialah asas perpaduan. Ia memastikan tiada pergaduhan, mengekalkan keharmonian dan kesejahteraan negara, mengukuhkan semangat patriotisme dan mengelakkan salah faham antara kaum.', 'Tepat! Kanak-kanak itu bersalaman dan satu kumpulan mengajar kumpulan lain mengucap salam dalam dua bahasa.'),
(NULL, 'e4_n3_s8', 'hint', 'Berkongsi maklumat memupuk persefahaman.', NULL, NULL),
(424, NULL, 'hint', 'Pelancong, patriotisme, warisan, persefahaman dan perpaduan.', 'Keunikan seni warisan menarik pelancong, keunikan seni tradisional memupuk patriotisme, keunikan budaya tempatan ialah warisan yang perlu dipelihara, perkongsian maklumat memupuk persefahaman, dan hormat-menghormati mengeratkan perpaduan antara kaum.', 'Cemerlang! Murid itu mengangkat tangan dan berjanji akan membawa kawan-kawannya ke pameran seterusnya.');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(61, 401, NULL, 'Tugasku ialah menjaga rentak setiap kaum supaya tidak hilang ditelan zaman. Jika satu bunyi terlupa, satu cerita ikut hilang, {nama}.', 1),
(61, 401, NULL, 'Aku belajar bahawa alat muzik dan tarian pelbagai kaum memperlihatkan kebijaksanaan nenek moyang dan menjadi warisan yang perlu kita hargai bersama.', 2),
(61, 401, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemuzik yang mengembara membawa alat muzik pelbagai kaum. Dengar setiap rentak dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(60, 401, 'e4_n1_s1', 'Pakcik Pemuzik! Hujan petang tadi melunturkan kad ucapan saya. Malam ini saya mesti menyambut tetamu dalam bahasa mereka sendiri, namun saya telah tidak ingat siapakah bercakap apa.', 1),
(69, 401, 'e4_n1_s1', 'Datuk saya berbual Hokkien, pakcik. Namun kawan-kawan lain di pekan ada yang bertutur Mandarin, Hakka atau Kantonis. Semuanya Cina juga.', 2),
(65, 401, 'e4_n1_s1', 'Ketahuilah, kami di rumah bercakap Tamil. Ada keluarga India yang memakai Telugu, dan ada yang Malayalam.', 3),
(64, 401, 'e4_n1_s1', 'Orang Melayu tentulah bahasa Melayu. Jiran saya orang Sikh, dia bertutur Punjabi dengan ibunya.', 4),
(NULL, 401, 'e4_n1_s1', 'Usah lupa Melaka. Kaum Serani di sana bertutur Kristang dan bahasa Inggeris, manakala Baba dan Nyonya memakai dialek Melayu Baba.', 5),
(60, 401, 'e4_n1_s1', 'Banyaknya! Pakcik, tolong padankan semuanya di kad ini sebelum pentas dibuka. Namun kenapa pengacara perlu menyebut begitu banyak bahasa malam ini?', 6),
(70, 401, 'e4_n1_s2', 'Pakcik, budak bandar ini kata orang kami sama dengan orang Iban dan Bidayuh. Sakit telinga saya mendengarnya.', 1),
(74, 401, 'e4_n1_s2', 'Saya fikir semua orang di hutan itu satu kaum. Maaf, Tok Batin.', 2),
(70, 401, 'e4_n1_s2', 'Sesungguhnya, kami Orang Asli di Semenanjung ini terbahagi kepada tiga kumpulan besar, iaitu Negrito atau Semang, Senoi dan Melayu Proto. Kami terkenal kerana masih mengekalkan kraf tangan, ubat herba dan bahasa mengikut suku.', 3),
(NULL, 401, 'e4_n1_s2', 'Tok Batin menulis nota kecil untuk tuan hamba, namun hujan sempat menyiram dakwatnya. Biar aku bacakan perlahan-lahan.', 4),
(74, 401, 'e4_n1_s2', 'Pakcik, nota itu belum habis. Jadi siapakah sebenarnya tiga kumpulan besar Orang Asli itu, dan adakah mereka sama dengan kaum di Sarawak?', 5),
(69, 401, 'e4_n1_s3', 'Pakcik, di pasar malam Melaka ini ramai yang kata Baba dan Nyonya itu Cina biasa. Namun cara mereka bercakap lain benar.', 1),
(NULL, 401, 'e4_n1_s3', 'Sesungguhnya, mereka lahir daripada perkahwinan pedagang dari China dengan penduduk tempatan di Melaka. Sebab itu budaya mereka bercampur dengan budaya tempatan.', 2),
(65, 401, 'e4_n1_s3', 'Nenek saya pula bercerita tentang kaum Chetti. Datuk moyang mereka pedagang India yang berkahwin dengan penduduk tempatan dan mereka bertutur Melayu kreol.', 3),
(64, 401, 'e4_n1_s3', 'Kaum Serani dikenali sebagai orang Eurasia, kerana datuk moyang mereka orang Portugis. Tarian mereka yang paling popular ialah branyo dan frapeirra.', 4),
(71, 401, 'e4_n1_s3', 'Kaum Siam pula ramai di Kedah dan Perlis. Mereka menyambut Songkran dan beribadat di wat. Orang Sikh memakai sarban dan bertutur Punjabi.', 5),
(74, 401, 'e4_n1_s3', 'Pakcik, empat kad ini telah bercampur di meja. Selepas dipadankan, apakah yang menjadikan kaum peranakan ini unik?', 6),
(68, 401, 'e4_n1_s4', 'Di Sarawak, kaum Iban kaum yang paling ramai. Kami bertutur bahasa Iban, pakcik. Pakaian pua kumbu kami dipakai semasa Hari Gawai dan majlis perkahwinan.', 1),
(66, 401, 'e4_n1_s4', 'Kaum paling ramai di Sabah pula Kadazandusun, dan kami berbahasa mengikut dialek sukuan masing-masing. Pesta Kaamatan nanti kami keluarkan pakaian tradisi yang paling indah.', 2),
(68, 401, 'e4_n1_s4', 'Linda, usah sombong. Kaum lain di Sarawak pun banyak, ada Bidayuh, Kenyah dan Melanau.', 3),
(NULL, 401, 'e4_n1_s4', 'Kedua-duanya benar. Satu kaum terbesar di Sarawak, satu lagi di Sabah. Tetapi pengunjung malam ini mudah keliru, jadi biar aku baca catatan ini dengan teliti.', 4),
(66, 401, 'e4_n1_s4', 'Pakcik, jika kami tersilap catat, pengunjung akan menyangka kaum lain yang paling besar. Selepas membaca catatan itu, bagaimanakah kita hendak menghargai kedua-dua kaum ini?', 5),
(63, 401, 'e4_n1_s5', 'Pakcik Pemuzik, angin kuat tadi menjatuhkan papan petunjuk di pentas. Pasukan Sarawak telah berdiri di sudut Melayu!', 1),
(NULL, 401, 'e4_n1_s5', 'Tenang. Pentas ini ada lima sudut. Melayu dengan gambus dan angklung serta tarian makyung dan zapin. Cina dengan gendang, bo dan tarian singa.', 2),
(66, 401, 'e4_n1_s5', 'India pula ada veenai dan talam serta tarian bharata natyam. Sarawak dengan sape dan engkerurai serta tarian ngajat.', 3),
(68, 401, 'e4_n1_s5', 'Sabah dengan kulintangan dan sompoton, dan tarian sumazau yang kami banggakan.', 4),
(NULL, 401, 'e4_n1_s5', 'Kita cari lima sudut itu di pentas dan pasang semula papan petunjuk. Segera, persembahan Sabah hampir bermula.', 5),
(63, 401, 'e4_n1_s5', 'Pakcik, semua sudut telah ada di pentas ini. Pada pendapat pakcik, apa yang dibawa oleh alat muzik dan tarian ini kepada negara kita?', 6),
(74, 401, 'e4_n1_s6', 'Pakcik, kenapa kita masih simpan alat muzik lama begini? Saya boleh buat bunyi gambus dalam komputer sahaja.', 1),
(NULL, 401, 'e4_n1_s6', 'Cuba tengok bahan alat ini. Angklung dibuat daripada buluh yang diikat pada rangka yang disebut ancak. Gambus pula daripada kayu keras seperti pokok nangka.', 2),
(65, 401, 'e4_n1_s6', 'Nafiri dibuat daripada logam, lazimnya perak. Geduk ialah gendang dua muka yang ditutup dengan belulang lembu atau kerbau.', 3),
(66, 401, 'e4_n1_s6', 'Sape pula daripada kayu meranti dan dipetik talinya. Sompoton saya diperbuat daripada buluh yang dilekatkan pada labu kering dengan lilin kelulut.', 4),
(NULL, 401, 'e4_n1_s6', 'Semuanya daripada alam. Jikalau engkau tahu cara membuatnya, baru engkau sedar betapa bijaknya pencipta dahulu. Mari padankan alat dengan bahannya.', 5),
(74, 401, 'e4_n1_s6', 'Wah, lilin kelulut pun boleh jadi alat muzik. Pakcik, jadi kenapa alat muzik lama begini wajar kita jaga?', 6),
(65, 401, 'e4_n1_s7', 'Pakcik, tirai pentas hampir dibuka dan senarai tarian bercampur. Aku hendak menari bharata natyam namun namaku tercatat di bawah tarian lain.', 1),
(NULL, 401, 'e4_n1_s7', 'Biar aku betulkan. Makyung ialah seni drama yang ada lakonan, tarian, muzik dan nyanyian. Zapin pula hiburan semasa pesta dan majlis perkahwinan.', 2),
(69, 401, 'e4_n1_s7', 'Tarian singa kami untuk Tahun Baharu Cina. Ia lambang keharmonian.', 3),
(65, 401, 'e4_n1_s7', 'Bharata natyam pula membuka tirai persembahan kebudayaan India. Ia bermula sebelum persembahan lain.', 4),
(68, 401, 'e4_n1_s7', 'Ngajat ialah tarian kami semasa Hari Gawai dan upacara ritual. Sumazau pula tarian Kadazandusun untuk menghormati semangat padi.', 5),
(63, 401, 'e4_n1_s7', 'Pakcik, padankan semua tarian ini dengan tujuannya sebelum tirai dibuka. Mengapakah penting iringan muzik mengikut tarian yang benar?', 6),
(70, 401, 'e4_n1_s8', 'Anak-anak, di kampung kami tarian ini bernama sewang. Penarinya menghias diri dengan selempang bunga, daun kelapa, daun palas, daun nipah dan kulit kayu.', 1),
(74, 401, 'e4_n1_s8', 'Namun di atas tikar ada kad bhangra juga, Tok Batin. Yang mana sebenarnya tarian orang Asli?', 2),
(NULL, 401, 'e4_n1_s8', 'Alat muzik tarian itu ialah buluh centong, gendang, kereb, pensol dan tetawak. Ia untuk upacara ritual, perubatan dan majlis keramaian.', 3),
(65, 401, 'e4_n1_s8', 'Bhangra pula tarian orang Sikh. Iringannya dram dhol, harmonika dan tamborin.', 4),
(70, 401, 'e4_n1_s8', 'Dua kad itu tertukar oleh angin. Nak, baca dengan teliti dan pilih yang benar. Selepas itu, apa yang kita pelajari apabila mengenali tarian setiap kaum?', 5),
(62, 402, NULL, 'Tugasku ialah membuka peti cerita ini satu demi satu supaya cucu-cucu tahu bagaimana datuk nenek mereka hidup, {nama}.', 1),
(62, 402, NULL, 'Aku belajar bahawa petempatan dan kegiatan ekonomi dahulu berbeza, tetapi kini kita boleh tinggal bersama dan cerita rakyat memberi iktibar kepada kita.', 2),
(62, 402, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, nenek yang menyimpan cerita setiap kaum. Dengar soalan cucu-cucu dan jawab dengan sabar. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(64, 402, 'e4_n2_s1', 'Nenek, mengapakah kampung Melayu dahulu semuanya berdekatan sungai dan pantai? Saya tidak pernah nampak kampung di tengah padang pasir.', 1),
(62, 402, 'e4_n2_s1', 'Sebelum merdeka, orang tinggal mengikut kerja mereka, cucu. Orang Melayu tinggal di kampung, di pesisir pantai dan tepi sungai.', 2),
(62, 402, 'e4_n2_s1', 'Ada yang menjadi petani, nelayan atau peniaga kecil. Ada juga yang berkhidmat dalam perkhidmatan awam.', 3),
(74, 402, 'e4_n2_s1', 'Betulkah semua orang Melayu dahulu hanya menjadi petani, nenek?', 4),
(62, 402, 'e4_n2_s1', 'Tidak semua. Baca catatan di laci pertama ini dahulu, usah terus meneka. Ia menyebut siapakah yang tinggal di mana.', 5),
(64, 402, 'e4_n2_s1', 'Nenek, jika kami tersilap, kami akan mengajar orang lain dengan cerita yang salah. Jadi kenapa agaknya petempatan dahulu dekat dengan sungai dan pantai?', 6),
(69, 402, 'e4_n2_s2', 'Datuk saya pelombong dan peniaga di pekan. Dia tinggal di pekan sepanjang hidupnya dan tidak pernah ke ladang.', 1),
(65, 402, 'e4_n2_s2', 'Datuk saya bekerja di ladang, Ah Meng. Kami tinggal di pinggir bandar.', 2),
(62, 402, 'e4_n2_s2', 'Kedua-duanya benar. Orang Cina dahulu tinggal di pekan dan bandar sebagai pelombong dan peniaga.', 3),
(62, 402, 'e4_n2_s2', 'Orang India pula tinggal di ladang dan pinggir bandar. Mereka pekerja ladang, peniaga kecil dan pekerja pelabuhan.', 4),
(NULL, 402, 'e4_n2_s2', 'Nenek, saya padankan petempatan dan pekerjaan setiap kaum ya, agar Ah Meng dan Kavitha tidak berebut cerita.', 5),
(65, 402, 'e4_n2_s2', 'Sesungguhnya, selepas dipadankan, nenek, kenapa dua cerita yang nampak berbeza ini sebenarnya kedua-duanya benar?', 6),
(70, 402, 'e4_n2_s3', 'Datuk nenek kami tinggal jauh di pedalaman, cucu. Rumahnya daripada buluh, tikarnya daripada rotan.', 1),
(74, 402, 'e4_n2_s3', 'Nenek, apa yang mereka makan? Mereka tidak ke pasar?', 2),
(62, 402, 'e4_n2_s3', 'Mereka berburu dan mengutip hasil hutan. Mereka juga membuat kraf tangan seperti anyaman.', 3),
(62, 402, 'e4_n2_s3', 'Banyak di Perak, Selangor, Pahang, Kelantan dan Terengganu. Itu di pedalaman, jauh dari bandar.', 4),
(70, 402, 'e4_n2_s3', 'Jadi kami tidak mengambil tanah orang. Kami hanya mengambil apa yang hutan beri.', 5),
(74, 402, 'e4_n2_s3', 'Nenek, selepas membaca catatan ini, kenapa Orang Asli dahulu bergantung kepada hutan?', 6),
(67, 402, 'e4_n2_s4', 'Nenek, di Sarawak kaum kami tinggal di tepi sungai. Benar, kan?', 1),
(68, 402, 'e4_n2_s4', 'Benar sebahagiannya, Jenny. Kaum Iban dan Bisaya tinggal berhampiran lembah sungai dan menjadi petani.', 2),
(62, 402, 'e4_n2_s4', 'Kaum Bidayuh, Kenyah dan Kelabit tinggal di pedalaman. Mereka mengusahakan padi sawah, padi bukit dan mengutip hasil hutan.', 3),
(62, 402, 'e4_n2_s4', 'Orang Melayu, Melanau dan Kedayan tinggal di pesisir pantai. Mereka pedagang, pembuat perahu dan pengusaha sagu.', 4),
(67, 402, 'e4_n2_s4', 'Aku hendak cerita yang benar, nenek, bukan sekadar cerita yang sedap didengar.', 5),
(62, 402, 'e4_n2_s4', 'Marilah padankan kaum dengan tempat tinggal dan kerjanya. Namun cucu, menurut tuan hamba, kenapa kaum yang berbeza tinggal di tempat yang berbeza?', 6),
(66, 402, 'e4_n2_s5', 'Datuk saya mengusahakan padi di pedalaman, nenek. Kaum kami, Kadazandusun, ramai di sana.', 1),
(71, 402, 'e4_n2_s5', 'Kaum kami, Bajau, bekerja sebagai petani atau nelayan, Linda.', 2),
(62, 402, 'e4_n2_s5', 'Murut juga tinggal di pedalaman. Mereka petani dan pengutip hasil hutan. Rungus pula terkenal dengan seni perusahaan kreatif.', 3),
(62, 402, 'e4_n2_s5', 'Di pesisir pantai ada Melayu Brunei, Iranun dan Suluk. Mereka nelayan, pembuat perahu dan pedagang.', 4),
(NULL, 402, 'e4_n2_s5', 'Ketahuilah, setiap kaum ada peranannya. Marilah kita padankan semuanya agar tiada yang tertukar.', 5),
(66, 402, 'e4_n2_s5', 'Selepas memadankannya nenek, apakah yang kita boleh simpulkan tentang kaum di Sabah?', 6),
(74, 402, 'e4_n2_s6', 'Nenek, jikalau dahulu setiap kaum tinggal berasingan mengikut pekerjaan, mengapakah kini kita semua boleh tinggal dalam satu taman perumahan?', 1),
(62, 402, 'e4_n2_s6', 'Sebelum merdeka, penduduk tinggal berdasarkan kegiatan ekonomi atau pekerjaan masing-masing, cucu.', 2),
(62, 402, 'e4_n2_s6', 'Selepas merdeka, negara semakin makmur dan pemimpin merancang pelbagai dasar pembangunan.', 3),
(62, 402, 'e4_n2_s6', 'Usaha menangani kegiatan ekonomi berasaskan kaum itu menampakkan kejayaan. Sikap toleransi diterapkan dan kita belajar bekerja bersama.', 4),
(64, 402, 'e4_n2_s6', 'Maka kini kita tinggal bersama dan hidup aman tanpa pemisahan tempat tinggal.', 5),
(62, 402, 'e4_n2_s6', 'Marilah susun peristiwa ini mengikut urutan. Namun cucu, apakah yang membolehkan rakyat hidup bersama dalam satu kawasan perumahan?', 6),
(72, 402, 'e4_n2_s7', 'Mereka kata aku nakal kerana mempermain-mainkan raja dan pembesar. Hukuman paling berat pun ditimpakan kepadaku.', 1),
(74, 402, 'e4_n2_s7', 'Nenek, bagaimanakah Si Luncai boleh terlepas daripada hukuman raja?', 2),
(62, 402, 'e4_n2_s7', 'Pesuruh raja memasukkan Si Luncai ke dalam guni dan membawanya dengan perahu ke tengah laut.', 3),
(72, 402, 'e4_n2_s7', 'Aku menyanyikan lagu ''Si Luncai terjun dengan labu-labunya''. Pesuruh raja ketawa dan lalai.', 4),
(62, 402, 'e4_n2_s7', 'Ketika mereka lalai, Si Luncai membiarkan labu-labu itu terapung dan melepaskan diri. Cerita rakyat ini milik bersama, cucu.', 5),
(62, 402, 'e4_n2_s7', 'Marilah susun kejadian ini satu demi satu. Namun cucu, apakah iktibar daripada kisah Si Luncai?', 6),
(73, 402, 'e4_n2_s8', 'Aku Puteri Santubong. Aku menenun kain untuk kampung kami.', 1),
(74, 402, 'e4_n2_s8', 'Nenek, mengapakah mereka bertukar menjadi gunung?', 2),
(62, 402, 'e4_n2_s8', 'Puteri Sejinjang mahir menumbuk padi. Kedua-duanya disukai oleh Putera Serapi, pemuda dari Matang.', 3),
(62, 402, 'e4_n2_s8', 'Dua puteri itu bertelingkah. Pasir Kuning dan Pasir Putih, dua kampung berjiran, mula berpecah sehingga mereka didamaikan.', 4),
(73, 402, 'e4_n2_s8', 'Kami dilarang bergaduh. Apabila syarat itu dilanggar, kami bertukar menjadi gunung.', 5),
(62, 402, 'e4_n2_s8', 'Marilah padankan watak dan peranan mereka dalam legenda ini. Namun cucu, apakah yang berlaku kepada mereka kerana melanggar syarat itu?', 6),
(63, 403, NULL, 'Tugasku ialah memastikan semua kanak-kanak bermain bersama, tanpa mengira kaum, supaya mereka belajar bekerjasama, {nama}.', 1),
(63, 403, NULL, 'Aku belajar bahawa permainan tradisional memupuk kerjasama, kreativiti dan persaingan sihat. Toleransi antara kaum ialah asas perpaduan.', 2),
(63, 403, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penjaga gelanggang permainan tradisional. Dengar sorakan kanak-kanak dan jawab dengan bijak. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(74, 403, 'e4_n3_s1', 'Tok, kenapa congkak dimainkan di anjung namun wau dimainkan di padang? Saya tak faham mana yang permainan anjung, laman dan lapang.', 1),
(63, 403, 'e4_n3_s1', 'Tiga jenis, nak. Permainan anjung seperti congkak, batu seremban, go dan chaturangam dimainkan di anjung rumah.', 2),
(63, 403, 'e4_n3_s1', 'Permainan laman seperti sepak raga dimainkan di laman. Permainan lapang seperti wau, gasing dan tibau perlukan padang yang luas.', 3),
(64, 403, 'e4_n3_s1', 'Kabaddi dan chap teh pun permainan laman, Tok.', 4),
(NULL, 403, 'e4_n3_s1', 'Marilah kita cari lima petunjuk di gelanggang ini agar semua kanak-kanak tidak tersilap tempat main.', 5),
(74, 403, 'e4_n3_s1', 'Tok, jikalau tersalah letak, kami bermain di tempat yang tidak sesuai. Jadi mengapakah permainan tradisional dibahagikan kepada tiga jenis?', 6),
(74, 403, 'e4_n3_s2', 'Tok, saya tersebut batu seremban sebagai congkak tadi. Betulkah beza dua-duanya?', 1),
(63, 403, 'e4_n3_s2', 'Congkak dimainkan dengan mengisi buah ke dalam lubang pada papan congkak.', 2),
(65, 403, 'e4_n3_s2', 'Batu seremban dimainkan dengan lima atau tujuh biji batu kecil yang dilambung dan disambut.', 3),
(69, 403, 'e4_n3_s2', 'Go atau Weiqi pula menggunakan buah hitam dan putih untuk menguasai kawasan papan yang lebih besar.', 4),
(64, 403, 'e4_n3_s2', 'Kabaddi ialah permainan dua pasukan, tujuh pemain, yang cuba menyentuh pihak lawan. Chap teh ditating dengan bola lawi bulu ayam, dipanggil tating lawi juga. Sepak raga pula bola rotan ditimang dengan kaki sejak zaman Kesultanan Melayu.', 5),
(74, 403, 'e4_n3_s2', 'Tolong padankan permainan dengan cara bermain agar tiada lagi perbalahan. Tok, apa yang patut kami buat sebelum bermain sesuatu permainan?', 6),
(74, 403, 'e4_n3_s3', 'Tok, permainan lapang boleh dimainkan di mana-mana sahaja, bukan?', 1),
(63, 403, 'e4_n3_s3', 'Wau lazimnya dimainkan selepas musim menuai, ketika padang lapang dan angin kuat.', 2),
(67, 403, 'e4_n3_s3', 'Tibau dimainkan semasa Pesta Kaul oleh masyarakat Melanau di Sarawak.', 3),
(66, 403, 'e4_n3_s3', 'Sepak manggis dimainkan di Kota Belud, Sabah, dalam majlis keramaian. Bola disepak untuk mendapat hadiah.', 4),
(63, 403, 'e4_n3_s3', 'Gasing ada gasing uri dan gasing pangkah. Padankan semuanya, nak.', 5),
(74, 403, 'e4_n3_s3', 'Tok, kenapa semua permainan ini dimainkan di padang, bukan di anjung?', 6),
(69, 403, 'e4_n3_s4', 'Tok, yoyo Cina dan go itu dari China. Orang Melayu tidak main, bukan?', 1),
(65, 403, 'e4_n3_s4', 'Kami main chaturangam dan paramapadham di rumah. Kedua-duanya datang dari India.', 2),
(63, 403, 'e4_n3_s4', 'Permainan di negara kita ada unsur dari Timur Tengah, China, India dan Alam Melayu. Semua dimainkan bersama.', 3),
(65, 403, 'e4_n3_s4', 'Chaturangam dimainkan oleh dua orang pemain, seolah-olah peperangan. Kemenangan bergantung pada menewaskan raja.', 4),
(NULL, 403, 'e4_n3_s4', 'Paramapadham pula seperti dam ular dan menggunakan dadu. Baca kad ini dan pilih permainan yang seperti catur.', 5),
(69, 403, 'e4_n3_s4', 'Tok, jadi apa maknanya apabila budak-budak pelbagai kaum bermain permainan dari budaya lain?', 6),
(74, 403, 'e4_n3_s5', 'Tok, bolehkah bola sepak dan badminton dikatakan permainan warisan?', 1),
(63, 403, 'e4_n3_s5', 'Tidak semua permainan tercatat dalam senarai warisan kebangsaan, nak.', 2),
(63, 403, 'e4_n3_s5', 'Papan di pintu ini menyenaraikan congkak, batu seremban, kabaddi, tating lawi dan menyumpit.', 3),
(66, 403, 'e4_n3_s5', 'Ada juga pistol buluh, sepak raga, ketinting, baling tin dan ketuk keli, Tok.', 4),
(63, 403, 'e4_n3_s5', 'Semuanya diangkat sebagai warisan kebangsaan agar generasi akan datang tidak melupakannya.', 5),
(74, 403, 'e4_n3_s5', 'Tok, saya baca papan itu dahulu. Namun kenapa permainan tradisional perlu diangkat sebagai warisan?', 6),
(66, 403, 'e4_n3_s6', 'Dalam cerita nenek moyang, di tepi Sungai Liwagu ada sebatang pohon nunuk yang besar. Penduduk berehat di bawahnya.', 1),
(71, 403, 'e4_n3_s6', 'Lalu seekor ayam gergasi merah bertaji emas mengibar sayap, dan penduduk terbang mengikutnya.', 2),
(66, 403, 'e4_n3_s6', 'Penduduk berpecah di Tambunan dan Ranau. Mereka membina dialek masing-masing.', 3),
(71, 403, 'e4_n3_s6', 'Itulah Nunuk Ragang. Ia kisah asal usul pelbagai kaum di Sabah.', 4),
(NULL, 403, 'e4_n3_s6', 'Marilah kita cari tiga petunjuk legenda ini di dalam gambar.', 5),
(66, 403, 'e4_n3_s6', 'Jikalau tersilap, asal usul kaum kami menjadi kabur. Jadi, apakah yang kita pelajari daripada legenda Nunuk Ragang?', 6),
(74, 403, 'e4_n3_s7', 'Maka mereka bercakap bahasa lain dan ketawa. Saya rasa mereka mengejek kami.', 1),
(69, 403, 'e4_n3_s7', 'Kami hanya bercakap Hokkien dengan datuk. Mengapakah tuan hamba marah?', 2),
(63, 403, 'e4_n3_s7', 'Jikalau tidak bertoleransi, perbalahan kecil boleh menjadi pergaduhan besar.', 3),
(63, 403, 'e4_n3_s7', 'Toleransi menjaga keharmonian dan kesejahteraan negara. Ia mengukuhkan semangat patriotisme dan mengelakkan salah faham antara kaum.', 4),
(NULL, 403, 'e4_n3_s7', 'Marilah baca kad ini dan fikirkan kepentingan toleransi antara kaum.', 5),
(63, 403, 'e4_n3_s7', 'Namun budak-budak ini masih berdiri begitu. Pada pendapat tuan hamba, apa yang perlu kita lakukan apabila tidak faham bahasa orang lain?', 6),
(74, 403, 'e4_n3_s8', 'Tok, untuk apa kita simpan semua budaya lama ini? Siapakah yang peduli?', 1),
(64, 403, 'e4_n3_s8', 'Pelancong itu peduli. Mereka datang kerana keunikan seni warisan kita.', 2),
(63, 403, 'e4_n3_s8', 'Keunikan seni tradisional kita berbeza daripada negara lain. Ia memupuk semangat patriotisme dalam diri rakyat.', 3),
(63, 403, 'e4_n3_s8', 'Keunikan budaya tempatan ialah warisan negara yang perlu dipelihara. Berkongsi maklumat tentang kaum pula memupuk persefahaman.', 4),
(NULL, 403, 'e4_n3_s8', 'Hormat-menghormati mengeratkan perpaduan. Marilah padankan kepentingannya.', 5),
(74, 403, 'e4_n3_s8', 'Tok, jikalau begitu, apa yang patut saya lakukan agar budaya ini terus hidup?', 6);
INSERT INTO QuestionBank (bankID, eraID) VALUES (4, 4)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(401, 4, 'Kaum manakah merupakan kaum terbesar di Sarawak?', 'Bidayuh', 'Melanau', 'Kenyah', 'Iban', 'D', 'Pakaian pua kumbu dan Hari Gawai.', 'Iban ialah kaum terbesar di Sarawak.'),
(402, 4, 'Kaum manakah merupakan kaum terbesar di Sabah?', 'Bajau', 'Murut', 'Kadazandusun', 'Rungus', 'C', 'Pesta Kaamatan.', 'Kadazandusun ialah kaum terbesar di Sabah.'),
(403, 4, 'Pakaian tradisional wanita Cina yang biasanya diperbuat daripada kain lembut seperti sutera ialah...', 'sari', 'ceongsam', 'kebaya', 'baju kurung', 'B', 'Pasangannya changsan untuk lelaki.', 'Ceongsam ialah pakaian tradisional wanita Cina; changsan untuk lelaki.'),
(404, 4, 'Kebanyakan kaum India bertutur dalam bahasa...', 'Tamil', 'Punjabi', 'Hokkien', 'Kristang', 'A', 'Ada juga Telugu dan Malayalam.', 'Kebanyakan kaum India bertutur dalam bahasa Tamil.'),
(405, 4, 'Tiga kumpulan terbesar Orang Asli di Semenanjung ialah...', 'Iban, Bidayuh dan Melanau', 'Murut, Rungus dan Bajau', 'Baba, Chetti dan Serani', 'Negrito (Semang), Senoi dan Melayu Proto', 'D', 'Salah satunya Semang.', 'Orang Asli terbahagi kepada Negrito (Semang), Senoi dan Melayu Proto.'),
(406, 4, 'Apakah dialek yang digunakan oleh masyarakat Baba dan Nyonya?', 'Melayu Sarawak', 'Bahasa Cina', 'Melayu Baba', 'Hokkien', 'C', 'Dialek tempatan di Melaka.', 'Baba dan Nyonya bertutur menggunakan dialek Melayu Baba.'),
(407, 4, 'Kaum Serani bertutur menggunakan bahasa...', 'Punjabi dan bahasa Siam', 'Kristang dan bahasa Inggeris', 'Tamil dan Telugu', 'Mandarin dan Hakka', 'B', 'Hasil perkahwinan orang Portugis dengan penduduk tempatan.', 'Kaum Serani menggunakan bahasa Kristang dan bahasa Inggeris.'),
(408, 4, 'Apakah nama tarian tradisional kaum Serani?', 'Branyo dan frapeirra', 'Zapin dan joget', 'Sumazau dan magunatip', 'Kuda kepang dan ulek mayang', 'A', 'Tarian yang paling popular.', 'Tarian yang paling popular dalam kaum Serani ialah branyo dan frapeirra.'),
(409, 4, 'Kaum manakah menyambut perayaan Songkran dan beribadat di wat?', 'Sikh', 'Chetti', 'Serani', 'Siam', 'D', 'Petempatan di Kedah, Kelantan, Perlis, Pulau Pinang dan Perak.', 'Kaum Siam menyambut Songkran dan menghadiri upacara di wat.'),
(410, 4, 'Apakah bahasa ibunda masyarakat Sikh?', 'Bahasa Tamil', 'Bahasa Kristang', 'Bahasa Punjabi', 'Bahasa Iban', 'C', 'Mereka memakai sarban.', 'Bahasa Punjabi ialah bahasa ibunda masyarakat Sikh.'),
(411, 4, 'Apakah pekerjaan masyarakat Cina pada masa dahulu?', 'Petani dan nelayan', 'Pelombong dan peniaga', 'Penjawat awam dan guru', 'Pengutip hasil hutan dan pemburu', 'B', 'Tinggal di pekan dan bandar.', 'Masyarakat Cina dahulu tinggal di pekan dan bandar sebagai pelombong dan peniaga.'),
(412, 4, 'Antara berikut, yang manakah kegiatan ekonomi masyarakat Orang Asli dahulu?', 'Berburu dan kegiatan kraf tangan', 'Pelombongan bijih timah', 'Penternakan haiwan secara besar-besaran', 'Perniagaan di bandar', 'A', 'Mereka tinggal di pedalaman.', 'Orang Asli dahulu berburu, mengutip hasil hutan dan membuat kraf tangan.'),
(413, 4, 'Kaum Iban dan Bisaya di Sarawak dahulu tinggal berhampiran...', 'pesisir pantai dan menjadi nelayan', 'pedalaman sebagai pemburu', 'bandar sebagai peniaga', 'lembah sungai dan menjadi petani', 'D', 'Dekat sungai.', 'Kaum Iban dan Bisaya tinggal berhampiran lembah sungai dan menjadi petani.'),
(414, 4, 'Kaum manakah di Sabah bekerja sebagai petani atau nelayan?', 'Murut', 'Rungus', 'Bajau', 'Kadazandusun', 'C', 'Terdapat juga di pesisir.', 'Kaum Bajau di Sabah bekerja sebagai petani atau nelayan.'),
(415, 4, 'Apakah perubahan petempatan masyarakat Malaysia sehingga kini?', 'Masih berasingan mengikut kaum', 'Tidak lagi berasingan mengikut kegiatan ekonomi', 'Semua tinggal di ladang', 'Semua tinggal di pedalaman', 'B', 'Toleransi dan kemakmuran.', 'Kini tidak berlaku pengasingan petempatan mengikut kegiatan ekonomi.'),
(416, 4, 'Gambus diperbuat daripada kayu keras seperti kayu pokok...', 'nangka', 'meranti', 'belian', 'merbau', 'A', 'Pokok yang berbuah besar.', 'Gambus diperbuat daripada kayu keras seperti kayu pokok nangka.'),
(417, 4, 'Alat muzik Melayu yang diperbuat daripada logam, lazimnya perak, ialah...', 'angklung', 'geduk', 'gambus', 'nafiri', 'D', 'Bahagian serombongnya agak leper.', 'Nafiri diperbuat daripada logam, lazimnya perak.'),
(418, 4, 'Alat muzik manakah dimainkan oleh masyarakat India?', 'Sape', 'Sompoton', 'Veenai', 'Geduk', 'C', 'Mempunyai tujuh tali logam.', 'Veenai ialah alat muzik masyarakat India; pullangkulal, talam dan mattalam juga.'),
(419, 4, 'Alat muzik bertali yang banyak dimainkan oleh kaum Kayan, Kelabit dan Kenyah ialah...', 'engkerurai', 'sape', 'tontog', 'kulintangan', 'B', 'Diperbuat daripada kayu meranti.', 'Sape banyak dimainkan oleh kaum Kayan, Kelabit dan Kenyah.'),
(420, 4, 'Kulintangan banyak dimainkan oleh kaum...', 'Bajau dan Kadazandusun', 'Iban dan Melanau', 'Melayu dan Cina', 'Sikh dan Siam', 'A', 'Sekumpulan gong kecil.', 'Kulintangan banyak dimainkan oleh kaum Bajau dan Kadazandusun.'),
(421, 4, 'Tarian yang disebut sumazau oleh kaum Kadazan dan sumayau oleh kaum Dusun ialah...', 'tarian pembuka tirai', 'tarian singa', 'tarian untuk perubatan Orang Asli', 'tarian untuk menghormati semangat padi', 'D', 'Diadakan semasa Pesta Kaamatan.', 'Sumazau dipersembahkan bagi menghormati semangat padi.'),
(422, 4, 'Tarian singa dipersembahkan antaranya untuk merayakan...', 'Hari Gawai', 'Pesta Kaamatan', 'Tahun Baharu Cina', 'Hari Raya Aidilfitri', 'C', 'Diiringi bo, gendang besar dan gong.', 'Tarian singa dipersembahkan untuk Tahun Baharu Cina dan majlis tertentu.'),
(423, 4, 'Tarian ngajat dipersembahkan semasa...', 'Pesta Kaamatan', 'Hari Gawai', 'Songkran', 'Tahun Baharu Cina', 'B', 'Tarian kaum Iban.', 'Tarian ngajat dipersembahkan semasa Hari Gawai dan upacara ritual.'),
(424, 4, 'Tarian bhangra ditarikan oleh masyarakat...', 'Sikh', 'Siam', 'Chetti', 'Melayu', 'A', 'Diiringi dram dhol.', 'Tarian bhangra ditarikan oleh masyarakat Sikh.'),
(425, 4, 'Antara berikut, yang manakah permainan laman?', 'Congkak dan paramapadham', 'Wau dan gasing', 'Tibau dan sepak manggis', 'Sepak raga dan kabaddi', 'D', 'Pilih dua permainan laman.', 'Sepak raga, chap teh dan kabaddi ialah permainan laman.'),
(426, 4, 'Congkak dan batu seremban dikategorikan sebagai...', 'permainan laman', 'permainan kawasan lapang', 'permainan anjung', 'permainan air', 'C', 'Dimainkan di bahagian rumah.', 'Congkak dan batu seremban ialah permainan anjung.'),
(427, 4, 'Wau, gasing dan tibau dikategorikan sebagai...', 'permainan anjung', 'permainan kawasan lapang', 'permainan laman', 'permainan dalam rumah', 'B', 'Memerlukan padang luas.', 'Wau, gasing, tibau dan sepak manggis ialah permainan kawasan lapang.'),
(428, 4, 'Permainan tibau dimainkan semasa Pesta Kaul oleh masyarakat...', 'Melanau', 'Iban', 'Bidayuh', 'Bajau', 'A', 'Sarawak.', 'Tibau dimainkan semasa Pesta Kaul oleh masyarakat Melanau.'),
(429, 4, 'Permainan tradisional yang dikenali juga sebagai tating lawi ialah...', 'kabaddi', 'sepak raga', 'congkak', 'chap teh', 'D', 'Bola lawi bulu ayam.', 'Chap teh disebut tating lawi oleh masyarakat Melayu.'),
(430, 4, 'Siapakah watak yang terkenal dengan kebijaksanaan dalam cerita Si Luncai dengan Labu-labunya?', 'Raja', 'Pesuruh raja', 'Si Luncai', 'Pembesar', 'C', 'Menggunakan labu air.', 'Si Luncai bijak memperdaya pesuruh raja; iktibar: jangan mempersendakan orang lain.'),
(431, 4, 'Apakah iktibar cerita Legenda Santubong Sang Puteri?', 'Jangan mempersendakan orang lain', 'Jangan bertengkar sesama sendiri', 'Menghargai asal usul keturunan', 'Menghormati orang tua', 'B', 'Mereka bertukar menjadi gunung.', 'Iktibar legenda Santubong: jangan bertengkar sesama sendiri.'),
(432, 4, 'Legenda Nunuk Ragang mengajar kita untuk...', 'menghargai asal usul keturunan', 'mempersendakan orang lain', 'bertengkar sesama sendiri', 'meninggalkan kampung halaman', 'A', 'Berkaitan kaum di Tambunan dan Ranau.', 'Iktibar Nunuk Ragang: menghargai asal usul keturunan.'),
(433, 4, 'Apakah kepentingan bertoleransi antara kaum sebagai asas perpaduan?', 'Menambah pergaduhan antara kaum', 'Mengelakkan persefahaman', 'Mengurangkan patriotisme', 'Mengekalkan keharmonian dan kesejahteraan negara', 'D', 'Pilih yang positif.', 'Toleransi memastikan tiada pergaduhan dan mengekalkan keharmonian.'),
(434, 4, 'Mengapakah kita perlu berkongsi maklumat tentang kepelbagaian kaum?', 'Menambah salah faham', 'Menjauhkan satu kaum daripada yang lain', 'Memupuk persefahaman dan mengeratkan perpaduan', 'Mengelakkan hormat-menghormati', 'C', 'Fikirkan perpaduan.', 'Berkongsi maklumat memupuk persefahaman, mengeratkan perpaduan dan hormat-menghormati.'),
(435, 4, 'Kaum Melayu Brunei, Iranun dan Suluk di Sabah dahulu tinggal di kawasan pesisir pantai. Pekerjaan yang paling sesuai bagi mereka ialah...', 'Pelombong bijih timah di pedalaman', 'Nelayan, pembuat perahu dan pedagang', 'Pekerja ladang getah di pinggir bandar', 'Pemburu dan pengutip hasil hutan', 'B', 'Fikirkan sumber di tepi laut.', 'Kaum Melayu Brunei, Iranun dan Suluk tinggal di pesisir pantai dan bekerja sebagai nelayan, pembuat perahu serta pedagang.'),
(436, 4, 'Dahulu petempatan penduduk berasingan mengikut kegiatan ekonomi. Mengapakah keadaan itu berubah pada masa kini?', 'Kemakmuran dan toleransi membolehkan rakyat tinggal serta bekerja bersama', 'Semua kaum berpindah ke pedalaman untuk bertani semula', 'Kegiatan ekonomi dihentikan sepenuhnya di semua kawasan', 'Setiap kaum diarah tinggal di kawasan yang sama kaum sahaja', 'A', 'Ingat Malaysia selepas merdeka.', 'Selepas merdeka, kemakmuran ekonomi dan sikap toleransi membolehkan rakyat hidup bersama tanpa pemisahan tempat tinggal.'),
(437, 4, 'Kini rakyat Malaysia bekerja dalam sektor kerajaan dan swasta tanpa mengira kaum dan agama. Apakah kesan paling baik kepada negara?', 'Jurang antara kaum semakin melebar setiap tahun', 'Setiap kaum hanya mengenali kaumnya sendiri sahaja', 'Kegiatan ekonomi bertambah asing dan terpisah', 'Perpaduan kukuh dan kesejahteraan dinikmati bersama', 'D', 'Bandingkan dengan zaman petempatan berasingan.', 'Bekerja bersama tanpa mengira kaum mengukuhkan perpaduan dan kesejahteraan negara.'),
(438, 4, 'Gendang terdapat dalam kebudayaan Melayu (geduk), Cina, India (mattalam) dan Sabah (tontog). Apakah persamaan alat muzik ini?', 'Semuanya diperbuat daripada logam yang sama jenis', 'Semuanya dimainkan dengan cara ditiup menggunakan mulut', 'Menggunakan bahan semula jadi dan dimainkan dengan cara dipukul', 'Semuanya hanya dimainkan oleh satu kaum sahaja', 'C', 'Lihat bahan dan cara memainkan.', 'Alat muzik ini menggunakan bahan alam seperti kayu dan kulit haiwan, dan dimainkan dengan cara dipukul.'),
(439, 4, 'Mengapakah alat muzik tradisional dikatakan menunjukkan kebijaksanaan penciptanya?', 'Kerana semuanya dibeli dari luar negara dengan harga mahal', 'Kerana dibuat daripada sumber alam yang ada di sekeliling mereka', 'Kerana semuanya dibuat oleh mesin di sebuah kilang besar', 'Kerana semuanya diperbuat daripada logam yang mahal harganya', 'B', 'Fikirkan buluh, kayu dan kulit haiwan.', 'Pencipta menggunakan sumber alam seperti buluh, kayu dan kulit haiwan untuk menghasilkan bunyi.'),
(440, 4, 'Sekolah anda mahu mencipta alat muzik daripada bahan terpakai. Manakah cadangan yang paling kreatif dan selamat?', 'Menggunakan straw dan tin yang dibersihkan', 'Menggunakan kaca pecah yang tajam', 'Membeli alat muzik siap dari kedai', 'Membuang bahan terpakai ke dalam sungai', 'A', 'Kreatif dan menjaga alam.', 'Bahan terpakai seperti straw dan tin boleh dijadikan alat muzik secara kreatif apabila dibersihkan dan digunakan dengan selamat.'),
(441, 4, 'Pelancong asing datang melihat tarian dan alat muzik pelbagai kaum di negara kita. Apakah tindakan murid yang paling sesuai?', 'Mengabaikannya kerana dianggap sudah lapuk', 'Menyembunyikannya daripada semua orang luar', 'Menukarnya dengan budaya asing sepenuhnya sekarang', 'Mempelajari dan memperkenalkan warisan itu dengan bangga', 'D', 'Kaitkan dengan menghargai keunikan budaya.', 'Keunikan budaya menarik pelancong dan perlu dipelihara serta diperkenalkan dengan bangga.'),
(442, 4, 'Dua kumpulan kanak-kanak berlainan kaum tidak memahami bahasa satu sama lain. Apakah langkah terbaik untuk mengelakkan salah faham?', 'Melarang mereka berbual antara satu sama lain langsung', 'Menyalahkan satu kumpulan sahaja tanpa bertanya', 'Bertanya dengan hormat dan berkongsi maklumat budaya', 'Membiarkan mereka berpisah dan tidak bertegur sapa', 'C', 'Fikirkan toleransi dan perkongsian maklumat.', 'Bertanya dengan hormat dan berkongsi maklumat memupuk persefahaman dan mengelakkan salah faham.'),
(443, 4, 'Kad mengatakan chap teh dan kabaddi dimainkan di laman. Murid mahu mencipta permainan baharu secara kreatif. Apakah cadangan yang bermakna?', 'Menghapuskan semua permainan tradisional yang lama', 'Menggabungkan peraturan beberapa permainan dengan selamat', 'Mencipta permainan baharu tanpa sebarang peraturan', 'Menukar semua permainan menjadi aktiviti bersendirian sahaja', 'B', 'Kreativiti dalam permainan tradisional.', 'Mengembangkan kreativiti permainan tradisional boleh dilakukan dengan menggabungkan peraturan secara selamat.');
